  1→//! Scribe - Document actor for reactive CRDT synchronization
  2→//!
  3→//! **Context**: Each open page gets its own Scribe that owns LoroDoc layers
  4→//! and handles bidirectional sync with permission-aware merge logic.
  5→//!
  6→//! **Key responsibilities:**
  7→//! - Own LoroDoc layers for a page
  8→//! - Handle permission checks (viewer/submitter/collaborator)
  9→//! - Apply sync policies (local_only, no_incoming_updates, send_full_snapshot)
 10→//! - Broadcast updates to subscribed PeerActors
 11→//! - Notify UI subscribers of changes
 12→
 13→use std::collections::HashMap;
 14→use std::sync::{Arc, Mutex};
 15→
 16→use ractor::{Actor, ActorProcessingErr, ActorRef};
 17→use tokio::time::{interval, Duration};
 18→use tracing::{debug, error, info, instrument, trace, warn};
 19→
 20→use domains::Layer;
 21→
 22→use crate::layer_unit::LayerUnit;
 23→use crate::message;
 24→use crate::state::{ScribeArgs, ScribeState, SyncMode, normalize_layer_name};
 25→use crate::permit::glob_match;
 26→use crate::ephemeral::{
 27→    route_remote_ephemeral, emit_raw_ephemeral, emit_structured_ephemeral,
 28→    broadcast_ephemeral_to_subscribers,
 29→};
 30→use crate::{
 31→    ScribeMessage, ScribeError, Result,
 32→    sync, query, operations, loro_observer,
 33→};
 34→
 35→// Scribe Actor
 36→
 37→/// Scribe - Document sync actor
 38→///
 39→/// One Scribe per open page. Owns layers, handles sync, broadcasts to peers.
 40→pub struct Scribe;
 41→
 42→impl Scribe {
 43→    pub fn new() -> Self {
 44→        Self
 45→    }
 46→}
 47→
 48→impl Default for Scribe {
 49→    fn default() -> Self {
 50→        Self::new()
 51→    }
 52→}
 53→
 54→impl Actor for Scribe {
 55→    type Msg = ScribeMessage;
 56→    type State = ScribeState;
 57→    type Arguments = ScribeArgs;
 58→
 59→    #[instrument(skip_all, fields(page_id = %args.page_id))]
 60→    async fn pre_start(
 61→        &self,
 62→        myself: ActorRef<Self::Msg>,
 63→        args: Self::Arguments,
 64→    ) -> std::result::Result<Self::State, ActorProcessingErr> {
 65→        let mode_info = args
 66→            .sync_config
 67→            .as_ref()
 68→            .map(|c| format!("mode={:?}, target={:?}", c.mode, c.sync_target))
 69→            .unwrap_or_else(|| "no sync config".to_string());
 70→        info!(page_id = %args.page_id, %mode_info, "Scribe started");
 71→
 72→        // Note: Validation is now handled by kunki/ValidationService via ValidationHandle
 73→        // Derivation is handled by kunki/LuaRuntime
 74→        info!(
 75→            page_id = %args.page_id,
 76→            is_node = args.is_node,
 77→            has_validation_handle = args.validation_handle.is_some(),
 78→            "Scribe initialized (validation delegated to kunki)"
 79→        );
 80→
 81→        // Parse our permit using gurkha::Permit directly
 82→        let (our_permit, static_layers) = if let Some(ref permit_token) = args.our_permit {
 83→            match gurkha::Permit::from_token(permit_token) {
 84→                Ok(permit) => {
 85→                    let static_layers = permit.static_layers(&args.page_id, &args.our_did);
 86→                    info!(
 87→                        page_id = %args.page_id,
 88→                        role = %permit.relationship().unwrap_or("peer"),
 89→                        static_layer_count = static_layers.len(),
 90→                        "Parsed our permit via gurkha::Permit"
 91→                    );
 92→                    (Some(permit), static_layers)
 93→                }
 94→                Err(e) => {
 95→                    warn!(page_id = %args.page_id, error = ?e, "Failed to parse our permit");
 96→                    (None, Vec::new())
 97→                }
 98→            }
 99→        } else {
100→            debug!(page_id = %args.page_id, "No our_permit, defaulting to full access");
101→            (None, Vec::new())
102→        };
103→
104→        // Spawn periodic flush timer - saves dirty layers every 10 seconds
105→        // This prevents blocking the actor on every single operation
106→        let myself_clone = myself.clone();
107→        tokio::spawn(async move {
108→            let mut flush_interval = interval(Duration::from_secs(10));
109→            loop {
110→                flush_interval.tick().await;
111→                let _ = myself_clone.cast(ScribeMessage::Flush);
112→            }
113→        });
114→
115→        // Spawn periodic reconciliation timer - catches missed syncs every 30 seconds
116→        // Only for Node mode (Broadcast) - User mode (ToSource) relies on Node to initiate sync
117→        // This prevents bilateral reconciliation attempts that can cause sync storms
118→        let is_user_mode = args.sync_config.as_ref().map(|c| c.mode) == Some(SyncMode::ToSource);
119→        if !is_user_mode {
120→            let myself_reconcile = myself.clone();
121→            tokio::spawn(async move {
122→                let mut reconcile_interval = interval(Duration::from_secs(30));
123→                loop {
124→                    reconcile_interval.tick().await;
125→                    let _ = myself_reconcile.cast(ScribeMessage::ReconcileWithPeers);
126→                }
127→            });
128→        }
129→
130→        // Convert args.layers → LayerUnit instances
131→        let mut units: HashMap<String, LayerUnit> = args.layers
132→            .into_iter()
133→            .map(|(name, layer)| (name, LayerUnit::new(layer)))
134→            .collect();
135→
136→        let mut state = ScribeState {
137→            page_id: args.page_id,
138→            units: HashMap::new(), // Populated below
139→            subscribers: Arc::new(std::sync::RwLock::new(HashMap::new())),
140→            query_subscribers: HashMap::new(),
141→            // Storage traits
142→            layer_storage: args.layer_storage,
143→            vector_storage: args.vector_storage,
144→            peer_resolver: args.peer_resolver,
145→            permit_issuer: args.permit_issuer,
146→            // Sync configuration
147→            sync_config: args.sync_config,
148→            sync_event_tx: args.sync_event_tx,
149→            page_update_subscribers: Arc::new(std::sync::RwLock::new(Vec::new())),
150→            pending_update_source: Arc::new(Mutex::new(None)),
151→            validation_handle: args.validation_handle,
152→            our_permit,
153→            our_did: args.our_did.clone(),
154→            node_script_shutdown: None,
155→        };
156→
157→        // Pre-create static layers from permit (already extracted via PermitContext)
158→        // Static layers are fully known after expanding {page_id} and {aud}
159→        // Dynamic layers (with wildcards) are created on-demand during sync
160→        for layer_name in static_layers {
161→            if !units.contains_key(&layer_name) {
162→                info!(
163→                    page_id = %state.page_id,
164→                    layer = %layer_name,
165→                    "Pre-creating static layer from permit"
166→                );
167→                units.insert(layer_name, LayerUnit::new_empty());
168→            }
169→        }
170→
171→        // Set is_local_only on each unit based on permit
172→        for (name, unit) in units.iter_mut() {
173→            unit.set_local_only(!state.should_sync_layer(name));
174→        }
175→
176→        // Move units into state
177→        state.units = units;
178→
179→        // Set up Loro observers for all layers (including pre-created ones)
180→        // This ensures import() triggers broadcasts via observer pattern
181→        loro_observer::setup_observers_for_all_layers(&mut state);
182→
183→        // Emit EnsureSync on page open to trigger remote subscription
184→        // Flow: EnsureSync → Coordinator → (connect if needed) → RefreshSubscriptions → remote subscribes
185→        // Works for both ToSource mode (single sync_target) and Broadcast mode (all authorized users)
186→        if let Some(ref tx) = state.sync_event_tx {
187→            let sync_targets = sync::reconcile::get_sync_targets(&state);
188→            if sync_targets.is_empty() {
189→                debug!(page_id = %state.page_id, "No sync targets on page open");
190→            } else {
191→                info!(page_id = %state.page_id, targets = ?sync_targets, "Emitting EnsureSync for {} targets on page open", sync_targets.len());
192→                for user_did in sync_targets {
193→                    let event = message::SyncEvent::EnsureSync {
194→                        user_did: user_did.clone(),
195→                    };
196→                    match tx.try_send(event) {
197→                        Ok(()) => info!(user_did = %user_did, page_id = %state.page_id, "Emitted EnsureSync on page open"),
198→                        Err(e) => warn!(user_did = %user_did, error = %e, "Failed to emit EnsureSync on page open"),
199→                    }
200→                }
201→            }
202→        }
203→
204→        // Note: Node script spawning is handled by the caller (e.g., kunki's NodeRuntimeManager)
205→        // This keeps the Scribe actor storage-agnostic and focused on CRDT sync
206→
207→        Ok(state)
208→    }
209→
210→    #[instrument(level = "trace", skip_all, fields(page_id = %state.page_id))]
211→    async fn handle(
212→        &self,
213→        myself: ActorRef<Self::Msg>,
214→        message: Self::Msg,
215→        state: &mut Self::State,
216→    ) -> std::result::Result<(), ActorProcessingErr> {
217→        match message {
218→            ScribeMessage::Subscribe {
219→                user_did,
220→                device_id,
221→                broadcast_tx,
222→                ephemeral_tx,
223→                permit,
224→            } => {
225→                sync::handle_subscribe(state, user_did, device_id, broadcast_tx, ephemeral_tx, permit).await;
226→            }
227→
228→            ScribeMessage::Unsubscribe { user_did, device_id } => {
229→                sync::handle_unsubscribe(state, &user_did, &device_id).await;
230→            }
231→
232→            ScribeMessage::SubscribeToPageUpdates { tx } => {
233→                // Send PeerSubscribed for all currently subscribed peers
234→                // (peers that subscribed before this app opened)
235→                if let Ok(subs) = state.subscribers.read() {
236→                    info!(page_id = %state.page_id, peer_count = subs.len(), "Sending existing peers as PeerSubscribed");
237→                    for ((user_did, _device_id), _info) in subs.iter() {
238→                        let _ = tx.try_send(message::PageUpdate::PeerSubscribed {
239→                            did: user_did.clone(),
240→                            username: None,
241→                        });
242→                    }
243→                }
244→
245→                // Presence state is delivered via CRDT sync (presence layer snapshot)
246→                // No need to send OnlinePeers event — apps read from LayerChanged on {page_id}/presence
247→
248→                if let Ok(mut subs) = state.page_update_subscribers.write() {
249→                    subs.push(tx);
250→                    info!(page_id = %state.page_id, subscriber_count = subs.len(), "PageUpdate subscriber added");
251→                }
252→            }
253→
254→            ScribeMessage::ApplyUpdate {
255→                layer_name,
256→                update,
257→                from_peer,
258→                permit,
259→            } => {
260→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
261→                // Loro observer handles broadcast automatically after import()
262→                let _ = sync::handle_apply_update(
263→                    state,
264→                    &layer_name,
265→                    &update,
266→                    from_peer,
267→                    permit.as_deref(),
268→                )
269→                .await;
270→            }
271→
272→            ScribeMessage::ApplyUpdateWithResult {
273→                layer_name,
274→                update,
275→                from_peer,
276→                permit,
277→                reply,
278→            } => {
279→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
280→                // Loro observer handles broadcast automatically after import()
281→                let result = sync::handle_apply_update(
282→                    state,
283→                    &layer_name,
284→                    &update,
285→                    from_peer,
286→                    permit.as_deref(),
287→                )
288→                .await;
289→                let _ = reply.send(result);
290→            }
291→
292→            ScribeMessage::SyncRequest {
293→                layer_name,
294→                their_vector,
295→                reply,
296→            } => {
297→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
298→                let result = sync::handle_sync_request(state, &layer_name, &their_vector);
299→                let _ = reply.send(result);
300→            }
301→
302→            ScribeMessage::ExportSnapshot { layer_name, reply } => {
303→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
304→                let result = sync::handle_export_snapshot(state, &layer_name);
305→                let _ = reply.send(result);
306→            }
307→
308→            ScribeMessage::GetStateVector { layer_name, reply } => {
309→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
310→                let result = sync::handle_get_state_vector(state, &layer_name);
311→                let _ = reply.send(result);
312→            }
313→
314→            ScribeMessage::GetUpdatesSince {
315→                layer_name,
316→                state_vector,
317→                reply,
318→            } => {
319→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
320→                let result = sync::handle_get_updates_since(state, &layer_name, &state_vector);
321→                let _ = reply.send(result);
322→            }
323→
324→            ScribeMessage::ReplaceLayer {
325→                layer_name,
326→                snapshot,
327→                reply,
328→            } => {
329→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
330→                // Replace layer entirely with authoritative snapshot (SyncReset recovery)
331→                info!(layer = %layer_name, snapshot_len = snapshot.len(), "Replacing layer with authoritative snapshot");
332→                let result = match Layer::from_snapshot(&snapshot) {
333→                    Ok(layer) => {
334→                        let unit = state.units.entry(layer_name.clone()).or_insert_with(LayerUnit::new_empty);
335→                        unit.replace_layer(layer);
336→                        unit.mark_dirty();
337→                        info!(layer = %layer_name, "Layer replaced successfully");
338→                        Ok(())
339→                    }
340→                    Err(e) => {
341→                        error!(layer = %layer_name, error = %e, "Failed to parse snapshot for layer replacement");
342→                        Err(format!("Failed to parse snapshot: {}", e))
343→                    }
344→                };
345→                let _ = reply.send(result);
346→            }
347→
348→            ScribeMessage::Flush => {
349→                sync::handle_flush(state).await;
350→            }
351→
352→            ScribeMessage::EnsureLoroList { layer_name, reply } => {
353→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
354→                // Get existing layer or create new one (for list access)
355→                let is_new_layer = !state.units.contains_key(&layer_name);
356→                if is_new_layer {
357→                    let mut unit = LayerUnit::new_empty();
358→                    unit.set_local_only(!state.should_sync_layer(&layer_name));
359→                    unit.mark_dirty();
360→                    state.units.insert(layer_name.clone(), unit);
361→                    debug!(layer = %layer_name, "Created new layer for Lua list");
362→                    // Set up Loro observer for new layer to enable sync broadcasts
363→                    loro_observer::setup_layer_observer(state, &layer_name);
364→                    // Notify UI subscribers about the new layer
365→                    sync::notify_layer_discovered(state, &layer_name);
366→                }
367→                // Just confirm the layer exists, don't return handle
368→                let _ = reply.send(Ok(()));
369→            }
370→
371→            ScribeMessage::EnsureLoroMap { layer_name, reply } => {
372→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
373→                // Get existing layer or create new one (for map access)
374→                let is_new_layer = !state.units.contains_key(&layer_name);
375→                if is_new_layer {
376→                    let mut unit = LayerUnit::new_empty();
377→                    unit.set_local_only(!state.should_sync_layer(&layer_name));
378→                    unit.mark_dirty();
379→                    state.units.insert(layer_name.clone(), unit);
380→                    debug!(layer = %layer_name, "Created new layer for Lua map");
381→                    // Set up Loro observer for new layer to enable sync broadcasts
382→                    loro_observer::setup_layer_observer(state, &layer_name);
383→                }
384→                // Just confirm the layer exists, don't return handle
385→                let _ = reply.send(Ok(()));
386→            }
387→
388→            ScribeMessage::LayerExists { layer_name, reply } => {
389→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
390→                let exists = state.units.contains_key(&layer_name);
391→                let _ = reply.send(exists);
392→            }
393→
394→            // Typed read operations (for Lua bindings - avoids stale handles)
395→
396→            ScribeMessage::ListGet { layer_name, index, reply } => {
397→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
398→                let result = state.units.get(&layer_name)
399→                    .map(|unit| unit.layer())
400→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
401→                    .map(|layer| {
402→                        let list = layer.loro().get_list(layer_name.clone());
403→                        list.get(index).map(|v| {
404→                            let deep = v.get_deep_value();
405→                            domains::loro_value_to_json(deep)
406→                        })
407→                    });
408→                let _ = reply.send(result);
409→            }
410→
411→            ScribeMessage::ListLength { layer_name, reply } => {
412→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
413→                let result = state.units.get(&layer_name)
414→                    .map(|unit| unit.layer())
415→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
416→                    .map(|layer| {
417→                        let list = layer.loro().get_list(layer_name.clone());
418→                        list.len()
419→                    });
420→                let _ = reply.send(result);
421→            }
422→
423→            ScribeMessage::MapGet { layer_name, key, reply } => {
424→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
425→                let result = state.units.get(&layer_name)
426→                    .map(|unit| unit.layer())
427→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
428→                    .map(|layer| {
429→                        let map = layer.loro().get_map(layer_name.clone());
430→                        map.get(&key).map(|v| {
431→                            let deep = v.get_deep_value();
432→                            domains::loro_value_to_json(deep)
433→                        })
434→                    });
435→                let _ = reply.send(result);
436→            }
437→
438→            ScribeMessage::MapLength { layer_name, reply } => {
439→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
440→                let result = state.units.get(&layer_name)
441→                    .map(|unit| unit.layer())
442→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
443→                    .map(|layer| {
444→                        let map = layer.loro().get_map(layer_name.clone());
445→                        map.len()
446→                    });
447→                let _ = reply.send(result);
448→            }
449→
450→            ScribeMessage::MapKeys { layer_name, reply } => {
451→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
452→                let result = state.units.get(&layer_name)
453→                    .map(|unit| unit.layer())
454→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
455→                    .map(|layer| {
456→                        let map = layer.loro().get_map(layer_name.clone());
457→                        map.keys().map(|k| k.to_string()).collect()
458→                    });
459→                let _ = reply.send(result);
460→            }
461→
462→            ScribeMessage::ListLayers { pattern, reply } => {
463→                let pattern = normalize_layer_name(&pattern, &state.page_id);
464→                // Match layer names against glob pattern
465→                let matching: Vec<String> = state
466→                    .units
467→                    .keys()
468→                    .filter(|name| glob_match(&pattern, name))
469→                    .cloned()
470→                    .collect();
471→                let _ = reply.send(matching);
472→            }
473→
474→
475→            ScribeMessage::GetLayerData { layer_name, reply } => {
476→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
477→                let result = state.units.get(&layer_name)
478→                    .map(|unit| unit.layer().get_content(&layer_name))
479→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()));
480→                let _ = reply.send(result);
481→            }
482→
483→            ScribeMessage::UpdatePeerVector {
484→                user_did,
485→                device_id,
486→                layer_name,
487→                state_vector,
488→            } => {
489→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
490→                if let Ok(mut subs) = state.subscribers.write() {
491→                    if let Some(info) = subs.get_mut(&(user_did.clone(), device_id.clone())) {
492→                        info.vectors.insert(layer_name.clone(), state_vector);
493→                        trace!(user_did = %user_did, device_id = %device_id, layer_name = %layer_name, "Updated in-memory peer vector");
494→                    }
495→                }
496→            }
497→
498→            ScribeMessage::ReconcileWithPeers => {
499→                sync::handle_reconcile_with_peers(state).await;
500→            }
501→
502→            ScribeMessage::GetSnapshot { layer_name, reply } => {
503→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
