531→            }
532→
533→            ScribeMessage::UpdateFromJson {
534→                layer_name,
535→                path,
536→                value,
537→                reply,
538→            } => {
539→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
540→                let result = self
541→                    .handle_update_from_json(state, &layer_name, &path, value)
542→                    .await;
