569→                    warn!(error = %e, "ListInsert failed");
570→                }
571→            }
572→
573→            ScribeMessage::ListDelete {
574→                layer_name,
575→                path,
576→                index,
577→            } => {
578→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
579→                if let Err(e) = operations::handle_list_delete(state, &layer_name, &path, index).await {
580→                    warn!(error = %e, "ListDelete failed");
