592→                    warn!(error = %e, "MapInsert failed");
593→                }
594→            }
595→
596→            ScribeMessage::MapDelete {
597→                layer_name,
598→                path,
599→                key,
600→            } => {
601→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
