606→
607→            ScribeMessage::CounterInc {
608→                layer_name,
609→                path,
610→                amount,
611→            } => {
612→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
613→                if let Err(e) = operations::handle_counter_inc(state, &layer_name, &path, amount).await {
614→                    warn!(error = %e, "CounterInc failed");
615→                }
