617→
618→            ScribeMessage::CreateDynamicLayer { schema_key, layer_id, reply } => {
619→                let result = crate::layer_unit::handle_create_dynamic_layer(
620→                    state, &schema_key, &layer_id,
621→                );
622→                let _ = reply.send(result);
623→            }
624→
625→            ScribeMessage::AddLayerAccess { layer_name, did, reply } => {
626→                let result = crate::layer_unit::handle_add_layer_access(state, &layer_name, &did).await;
627→                let _ = reply.send(result);
628→            }
629→
630→            ScribeMessage::RemoveLayerAccess { layer_name, did, reply } => {
631→                let result = crate::layer_unit::handle_remove_layer_access(state, &layer_name, &did);
632→                let _ = reply.send(result);
633→            }
634→
635→            ScribeMessage::Shutdown => {
636→                info!(page_id = %state.page_id, "Scribe shutting down");
637→                sync::handle_flush(state).await;
638→                myself.stop(Some("shutdown".to_string()));
639→            }
640→
641→            // Ephemeral events (from datagrams via PeerActor)
642→            ScribeMessage::RemoteEphemeral { user_did, device_id, payload } => {
643→                // Log payload content for debugging
644→                let payload_str = std::str::from_utf8(&payload).unwrap_or("<binary>");
645→                debug!(
646→                    page_id = %state.page_id,
647→                    user_did = ?user_did,
648→                    device_id = ?device_id,
649→                    payload_len = payload.len(),
650→                    payload = %payload_str,
651→                    our_did = %state.our_did,
652→                    "Scribe received RemoteEphemeral"
653→                );
654→                // 1. Forward to local app layer (if we have sender info)
655→                if let Some(ref did) = user_did {
656→                    let handled = route_remote_ephemeral(state, did, &payload);
657→                    debug!(page_id = %state.page_id, handled = handled, our_did = %state.our_did, "route_remote_ephemeral returned");
658→                    if !handled {
659→                        let dev_id = device_id.as_deref().unwrap_or_default();
660→                        emit_raw_ephemeral(state, did, dev_id, &payload);
661→                    }
662→                } else {
663→                    debug!(page_id = %state.page_id, "RemoteEphemeral without user_did - not emitting to local app");
664→                }
665→
666→                // 2. Relay to other subscribers (node mode relay) - exclude sender
667→                let exclude = match (&user_did, &device_id) {
668→                    (Some(d), Some(dev)) => Some((d.as_str(), dev.as_str())),
669→                    _ => None,
670→                };
671→                broadcast_ephemeral_to_subscribers(state, &payload, exclude);
672→            }
673→
674→            ScribeMessage::SendEphemeral { payload } => {
675→                // Broadcast ephemeral data directly to all subscribed PeerActors
676→                // No exclusion - this is local user action, send to everyone
677→                debug!(page_id = %state.page_id, payload_len = payload.len(), "Broadcasting ephemeral to all subscribers");
678→                broadcast_ephemeral_to_subscribers(state, &payload, None);
679→            }
680→
681→            ScribeMessage::SendStructuredEphemeral { func, args } => {
682→                // Log the incoming request
683→                let has_permit = state.our_permit.is_some();
684→                let ephemeral_funcs = state.our_permit
685→                    .as_ref()
686→                    .map(|p| p.ephemeral_funcs().to_vec())
687→                    .unwrap_or_default();
688→                debug!(
689→                    page_id = %state.page_id,
690→                    func = %func,
691→                    has_permit = has_permit,
692→                    ephemeral_funcs = ?ephemeral_funcs,
693→                    our_did = %state.our_did,
694→                    "SendStructuredEphemeral received"
695→                );
696→
697→                // Validate func against our permit's ephemeral_funcs (if set)
698→                // Empty ephemeral_funcs list means all funcs allowed
699→                let can_send = state.our_permit
700→                    .as_ref()
701→                    .map(|p| p.can_send_ephemeral(&func))
702→                    .unwrap_or(true); // No permit = allow (local mode)
703→
704→                if !can_send {
705→                    warn!(page_id = %state.page_id, func = %func, "Structured ephemeral func not allowed by permit");
706→                    return Ok(());
707→                }
708→
709→                // Broadcast as StructuredEphemeral to app subscribers (local UI)
710→                let our_did = state.our_did.clone();
711→                emit_structured_ephemeral(state, &our_did, &func, &args);
712→
713→                // Also broadcast via ephemeral channel for remote peers
714→                // PeerActor should be subscribed to this Scribe with ephemeral_tx
715→                // Include from_did so relayed messages preserve original sender identity
716→                let payload = serde_json::json!({
717→                    "type": "structured",
718→                    "from_did": our_did,
719→                    "func": func,
720→                    "args": args
721→                });
722→                if let Ok(bytes) = serde_json::to_vec(&payload) {
723→                    debug!(
724→                        page_id = %state.page_id,
725→                        func = %func,
726→                        "Broadcasting structured ephemeral to PeerActor subscribers"
727→                    );
728→                    broadcast_ephemeral_to_subscribers(state, &bytes, None);
729→                }
730→            }
731→
732→            ScribeMessage::RemoteStructuredEphemeral { from_did, device_id, func, args } => {
733→                // Validate func against sender's permit
734→                let can_send = {
735→                    let subs = state.subscribers.read().ok();
736→                    subs.and_then(|s| {
737→                        s.get(&(from_did.clone(), device_id.clone()))
738→                            .map(|info| info.permit.can_send_ephemeral(&func))
739→                    }).unwrap_or(false) // Unknown sender = reject
740→                };
741→
742→                if !can_send {
743→                    warn!(
744→                        page_id = %state.page_id,
745→                        from_did = %from_did,
746→                        func = %func,
747→                        "Remote structured ephemeral rejected - func not allowed"
748→                    );
749→                    return Ok(());
750→                }
751→
752→                // Emit to local app subscribers
753→                emit_structured_ephemeral(state, &from_did, &func, &args);
754→
755→                debug!(
756→                    page_id = %state.page_id,
757→                    from_did = %from_did,
758→                    func = %func,
759→                    "Processed remote structured ephemeral"
760→                );
761→            }
762→
763→            // Note: Ephemeral events now go through SubscribeToPageUpdates (PageUpdate::Ephemeral)
764→
765→            // Derivation operations (now handled by kunki/LuaRuntime externally)
766→            ScribeMessage::RebuildDerived { target: _, reply } => {
767→                // Derivation is now handled by kunki, not Scribe
768→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
769→            }
770→
771→            ScribeMessage::RebuildAllDerived { reply } => {
772→                // Derivation is now handled by kunki, not Scribe
773→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
774→            }
775→
776→            ScribeMessage::IsDerivationEnabled { reply } => {
777→                // Derivation is now external, Scribe always returns false
778→                let _ = reply.send(false);
779→            }
780→
781→            ScribeMessage::CreateDerivedLayer { target_layer } => {
782→                let target_layer = normalize_layer_name(&target_layer, &state.page_id);
783→                // Create the derived layer (empty) so it exists for subscribers
784→                if !state.units.contains_key(&target_layer) {
785→                    let unit = LayerUnit::new_empty();
786→                    let _ = unit.layer().loro().get_map(target_layer.clone());
787→                    unit.layer().commit();
788→                    state.units.insert(target_layer.clone(), unit);
789→                    info!(target = %target_layer, "Created empty derived layer");
790→
791→                    // Set up observer for the new layer
792→                    loro_observer::setup_layer_observer(state, &target_layer);
793→                }
794→            }
795→
796→            ScribeMessage::GetAppFiles { app_name, reply } => {
797→                // Use bare layer name (Scribe uses bare names, no page_id/ prefix)
798→                let layer_name = format!("app:{}", app_name);
799→                let result = if let Some(unit) = state.units.get(&layer_name) {
800→                    Ok(unit.layer().get_all_files())
801→                } else {
802→                    Err(format!("App layer '{}' not found", layer_name))
803→                };
804→                let _ = reply.send(result);
805→            }
806→
807→            ScribeMessage::GetSubscriberCount { reply } => {
808→                let count = state.subscribers.read()
809→                    .map(|s| s.len())
810→                    .unwrap_or(0);
811→                let _ = reply.send(count);
812→            }
813→
814→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
815→                // RefreshApp requires filesystem access which is handled by butler's refresh service
816→                // This stub returns an error - callers should use butler's refresh functionality instead
817→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
818→            }
819→        }
820→
821→        Ok(())
822→    }
823→
824→    #[instrument(skip_all, fields(page_id = %state.page_id))]
825→    async fn post_stop(
826→        &self,
827→        _myself: ActorRef<Self::Msg>,
828→        state: &mut Self::State,
829→    ) -> std::result::Result<(), ActorProcessingErr> {
830→        // Flush any dirty layers before stopping
831→        let has_dirty = state.units.values().any(|u| u.is_dirty());
832→        if has_dirty {
833→            let dirty_count = state.units.values().filter(|u| u.is_dirty()).count();
834→            info!(page_id = %state.page_id, dirty_count = dirty_count, "Flushing dirty layers on shutdown");
835→            sync::handle_flush(state).await;
836→        }
837→
838→        // Stop node script if running
839→        if let Some(tx) = state.node_script_shutdown.take() {
840→            info!(page_id = %state.page_id, "Stopping node script tick loop");
841→            let _ = tx.send(()).await;
842→        }
843→
844→        info!(page_id = %state.page_id, "Scribe stopped");
845→        Ok(())
846→    }
847→}
848→
849→// Helper Methods
850→
851→impl Scribe {
852→    /// Handle JSON update from UI (CEL commit())
853→    ///
854→    /// **Broadcast**: Handled automatically by Loro observer after commit()
855→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
856→    async fn handle_update_from_json(
857→        &self,
858→        state: &mut ScribeState,
859→        layer_name: &str,
860→        path: &str,
861→        value: serde_json::Value,
862→    ) -> Result<()> {
863→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
864→
865→        // Get or create the layer unit
866→        let unit = state
867→            .units
868→            .entry(layer_name.to_string())
869→            .or_insert_with(LayerUnit::new_empty);
870→
871→        // Convert JSON to Loro and update
872→        unit.layer()
873→            .set_from_json(path, &value)
874→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
875→
876→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
877→        unit.layer().commit();
878→
879→        // Mark as dirty for persistence
880→        unit.mark_dirty();
881→
882→        debug!("Layer update from JSON complete, observer will broadcast");
883→        Ok(())
884→    }
885→}
886→
887→// Tests
888→
889→#[cfg(test)]
890→mod tests {
891→    use super::*;
892→    use crate::test_fixtures::node_scribe_args;
893→    use std::time::Duration;
894→
895→    /// Test that Scribe with no subscribers doesn't crash on ephemeral send
896→    #[tokio::test]
897→    async fn test_ephemeral_with_no_subscribers() {
898→        let args = node_scribe_args("test-page-456");
899→        let (scribe_ref, _handle) = ractor::Actor::spawn(
900→            Some("test-scribe-no-subs".to_string()),
901→            Scribe,
902→            args,
903→        ).await.expect("Failed to spawn Scribe");
904→
905→        // Send ephemeral with no subscribers - should not crash
906→        scribe_ref.cast(ScribeMessage::SendStructuredEphemeral {
907→            func: "typing".to_string(),
908→            args: serde_json::json!({"user": "TestUser"}),
909→        }).expect("Failed to send ephemeral");
910→
911→        // Small delay to ensure message is processed
912→        tokio::time::sleep(Duration::from_millis(50)).await;
913→
914→        println!("✓ Ephemeral with no subscribers handled gracefully");
915→        scribe_ref.stop(Some("test complete".to_string()));
916→    }
917→}
918→

