108→    if let Ok(mut subs) = state.subscribers.write() {
109→        subs.insert(
110→            (user_did.clone(), device_id.clone()),
111→            SubscriberInfo {
112→                permit: permit.clone(),
113→                layer_permits: Vec::new(),
114→                subscriber_did: permit_holder_did.clone(),
115→                is_visible,
116→                can_see_others,
117→                display_name: display_name.clone(),
118→                broadcast_tx: broadcast_tx.clone(),
119→                ephemeral_tx,
120→                vectors,
121→            },
122→        );
123→        debug!(subscriber_count = subs.len(), "Subscriber added");
124→    }
125→
126→    // Notify app subscribers about peer joining (lifecycle event)
127→    emit_peer_subscribed(state, &user_did);
128→
129→    // Send initial state to new subscriber for layers they have access to
130→    send_initial_state_to_subscriber(
131→        state,
132→        &user_did,
133→        &device_id,
134→        &broadcast_tx,
135→        &permit,
136→        &permit_holder_did,
137→    ).await;
