143→/// Handle peer unsubscription
144→#[instrument(skip(state), fields(page_id = %state.page_id))]
145→pub async fn handle_unsubscribe(
146→    state: &mut ScribeState,
147→    user_did: &str,
148→    device_id: &str,
149→) {
