153→        // Save their vectors before removing
154→        if let Some(info) = subs.get(&(user_did.to_string(), device_id.to_string())) {
155→            if let Err(e) = state.vector_storage.save_vectors(user_did, device_id, &info.vectors) {
156→                warn!(error = %e, "Failed to save peer vectors on unsubscribe");
157→            }
