159→
160→        subs.remove(&(user_did.to_string(), device_id.to_string()));
161→        debug!(subscriber_count = subs.len(), "Subscriber removed");
162→    }
163→
164→    // Notify app subscribers about peer leaving (lifecycle event)
165→    emit_peer_unsubscribed(state, user_did);
166→}
