170→/// Send initial state to a newly subscribed peer
171→///
172→/// **Context**: Peer just subscribed, may have missed previous updates
173→/// **We do**: Send current snapshot for each layer they have permission for
174→/// **Checks**: Uses permit.can_read_layer() which handles both fixed and pattern-based
175→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
176→async fn send_initial_state_to_subscriber(
177→    state: &ScribeState,
178→    user_did: &str,
179→    device_id: &str,
180→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
181→    permit: &gurkha::Permit,
182→    subscriber_did: &str,
183→) {
184→    // Get peer's stored vectors (if any), normalizing keys to bare names
185→    let peer_vectors = match state.vector_storage.load_vectors(user_did, device_id) {
186→        Ok(Some(v)) => v.into_iter()
187→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
188→            .collect(),
189→        Ok(None) => HashMap::new(),
190→        Err(_) => HashMap::new(),
191→    };
192→
193→    for (layer_name, unit) in &state.units {
194→        let layer = unit.layer();
195→
196→        // Skip layers in no_incoming_updates (from sync facts)
197→        if permit.sync_facts().no_incoming_updates.contains(&layer_name.to_string()) {
198→            continue;
199→        }
200→
201→        // Check if they can receive this layer using permit's can_read_layer
202→        // This handles both fixed layers and pattern-based permissions
203→        if !permit.can_read_layer(layer_name, &state.page_id, subscriber_did) {
204→            continue;
205→        }
206→
207→        // Determine what to send: incremental or full snapshot
208→        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
209→            if their_vector.is_empty() {
210→                layer.export_snapshot()
211→            } else {
212→                match layer.export_updates(their_vector) {
213→                    Ok(updates) if updates.is_empty() => {
214→                        // No new updates since their last sync
215→                        debug!(user_did = %user_did, layer = %layer_name, "No new updates for subscriber");
216→                        continue;
217→                    }
218→                    Ok(updates) => updates,
219→                    Err(e) => {
220→                        warn!(error = %e, layer = %layer_name, "Failed to export incremental, using snapshot");
221→                        layer.export_snapshot()
222→                    }
223→                }
224→            }
225→        } else {
226→            // No stored vector - send full snapshot
227→            layer.export_snapshot()
228→        };
229→
230→        // Get our current state vector for 3-step sync protocol
231→        let state_vector = layer.version_vector();
232→
233→        // Skip empty data or empty state vectors (no operations)
234→        // Empty LoroDoc has state_vector [0] (single byte indicating 0 entries)
235→        if data.is_empty() || state_vector.len() <= 1 {
236→            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer in initial state");
237→            continue;
238→        }
239→
240→        let payload = BroadcastPayload {
241→            page_id: state.page_id.clone(),
242→            layer_name: layer_name.clone(),
243→            layer_type: domains::LayerType::from_layer_name(layer_name),
244→            update: data,
245→            state_vector,
246→        };
247→
248→        if let Err(e) = broadcast_tx.try_send(payload) {
249→            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
250→        } else {
251→            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state to subscriber");
252→        }
253→    }
254→}
255→
256→/// Issue pending layer permits for a newly subscribed peer (node mode only)
257→///
258→/// **Context**: Peer just subscribed. Check if they're a participant in any explicit
259→/// dynamic layers and issue fresh permits.
260→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
261→async fn issue_pending_layer_permits(
262→    state: &ScribeState,
263→    user_did: &str,
264→    device_id: &str,
265→) {
266→    let Some(ref issuer) = state.permit_issuer else { return; };
267→    let Some(ref our_permit) = state.our_permit else { return; };
268→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
269→
270→    // Load all explicit dynamic layers and their participants
271→    let explicit_layers = match issuer.list_explicit_dynamic_layers() {
272→        Ok(layers) => layers,
273→        Err(e) => { warn!(error = %e, "Failed to list explicit dynamic layers"); return; }
274→    };
275→
276→    let mut all_permits = Vec::new();
277→    for (layer_name, participants) in &explicit_layers {
278→        if !participants.contains(&user_did.to_string()) { continue; }
279→
280→        // Find schema for permissions
281→        if let Some((_key, schema, _creator)) =
282→            find_matching_dynamic_schema(our_permit, layer_name, &state.page_id)
283→        {
284→            let config = schema.permissions.clone().unwrap_or(
285→                gurkha::LayerConfig { sync: true, write: true, layer_type: None }
286→            );
287→            match issuer.issue_layer_permit(user_did, layer_name, config) {
288→                Ok((token, _cid)) => {
289→                    // Add to subscriber's layer_permits
290→                    if let Ok(mut subs) = state.subscribers.write() {
291→                        if let Some(info) = subs.get_mut(&(user_did.to_string(), device_id.to_string())) {
292→                            if let Ok(p) = gurkha::Permit::from_token(&token) {
293→                                info.add_layer_permit(p);
294→                            }
295→                        }
296→                    }
297→                    all_permits.push((user_did.to_string(), token));
298→                }
299→                Err(e) => warn!(error = %e, layer = %layer_name, "Failed to issue pending layer permit"),
300→            }
301→        }
302→    }
303→
304→    // Emit permits for distribution via Coordinator
305→    if !all_permits.is_empty() {
306→        let event = SyncEvent::NewDynamicLayer {
307→            page_id: state.page_id.clone(),
308→            layer_name: "pending-layer-permits".to_string(),
309→            permits: all_permits,
310→        };
311→        if let Err(e) = sync_event_tx.send(event).await {
312→            warn!(error = %e, "Failed to emit pending layer permits");
313→        }
314→    }
315→}
