  1→//! Reconciliation handling for Scribe actor
  2→//!
  3→//! Handles periodic reconciliation with peers and sync target resolution.
  4→
  5→use tracing::{debug, warn, instrument};
  6→
  7→use super::broadcast::broadcast_update;
  8→use crate::message::SyncEvent;
  9→use crate::state::{ScribeState, SyncMode};
 10→
 11→// Periodic Reconciliation
 12→
 13→/// Handle periodic reconciliation with all subscribed peers
 14→///
 15→/// **Context**: Timer-driven check for state divergence (every 30s)
 16→/// **We do**: For each layer, check if any subscriber is behind our vector
 17→/// **If diverged**: Re-broadcast update (triggers 3-step sync to catch them up)
 18→#[instrument(skip(state), fields(page_id = %state.page_id))]
 19→pub async fn handle_reconcile_with_peers(state: &mut ScribeState) {
 20→    // Check if any subscribers exist (read lock)
 21→    let has_subscribers = state.subscribers.read()
 22→        .map(|s| !s.is_empty())
 23→        .unwrap_or(false);
 24→
 25→    if !has_subscribers {
 26→        return; // No subscribers to reconcile with
 27→    }
 28→
 29→    let sub_count = state.subscribers.read().map(|s| s.len()).unwrap_or(0);
 30→    debug!(subscriber_count = sub_count, layer_count = state.units.len(), "Starting periodic reconciliation");
 31→
 32→    // For each layer, check if any subscriber needs sync
 33→    let layer_names: Vec<String> = state.units.keys().cloned().collect();
 34→    for layer_name in layer_names {
 35→        let our_vector = match state.units.get(&layer_name) {
 36→            Some(unit) => unit.layer().version_vector(),
 37→            None => continue,
 38→        };
 39→
 40→        // Check if any subscriber has a different vector (may be behind)
 41→        let needs_sync = if let Ok(subs) = state.subscribers.read() {
 42→            subs.iter().any(|(_, info)| {
 43→                // Skip if they can't receive this layer (checks fixed AND pattern permissions)
 44→                if !info.can_receive_layer(&layer_name, &state.page_id) {
 45→                    return false;
 46→                }
 47→
 48→                // Compare vectors - if different or missing, they may need sync
 49→                info.vectors.get(&layer_name)
 50→                    .map(|v| v != &our_vector)
 51→                    .unwrap_or(true) // No vector = never synced = needs sync
 52→            })
 53→        } else {
 54→            false
 55→        };
 56→
 57→        if needs_sync {
 58→            debug!(layer_name = %layer_name, "Divergence detected during reconciliation, broadcasting");
 59→            broadcast_update(state, &layer_name, None).await;
 60→        }
 61→    }
 62→}
 63→
 64→// Sync Target Resolution
 65→
 66→/// Get user_dids that should receive updates for this page.
 67→///
 68→/// **Context**: Called during broadcast to find unsubscribed targets.
 69→/// **Returns**: Vec<String> of user_dids - Coordinator handles device resolution.
 70→#[instrument(skip(state), fields(page_id = %state.page_id))]
 71→pub fn get_sync_targets(state: &ScribeState) -> Vec<String> {
 72→    match state.sync_config.as_ref().map(|c| c.mode) {
 73→        Some(SyncMode::ToSource) => {
 74→            // User mode: single target (the node's DID)
 75→            state.sync_config.as_ref()
 76→                .and_then(|c| c.sync_target.as_ref())
 77→                .map(|node_did| vec![node_did.clone()])
 78→                .unwrap_or_default()
 79→        }
 80→        Some(SyncMode::Broadcast) | None => {
 81→            // Node mode: query storage for authorized user_dids
 82→            state.peer_resolver
 83→                .as_ref()
 84→                .map(|r| r.list_authorized_users())
 85→                .unwrap_or_default()
 86→        }
 87→    }
 88→}
 89→
 90→/// Check if a user is currently subscribed (by any device).
 91→///
 92→/// **Context**: Called during broadcast to filter already-subscribed users.
 93→pub fn is_user_subscribed(state: &ScribeState, user_did: &str) -> bool {
 94→    state.subscribers.read()
 95→        .map(|subs| subs.keys().any(|(did, _device)| did == user_did))
 96→        .unwrap_or(false)
 97→}
 98→
 99→/// Emit EnsureSync for users that should be synced but aren't subscribed.
100→///
101→/// **Context**: Called after broadcasting to current subscribers.
102→/// **We do**: Get sync targets, filter out already-subscribed, emit EnsureSync.
103→#[instrument(skip(state), fields(page_id = %state.page_id))]
104→pub fn emit_sync_events_for_missing_targets(state: &ScribeState) {
105→    let sync_targets = get_sync_targets(state);
106→
107→    for user_did in sync_targets {
108→        if is_user_subscribed(state, &user_did) {
109→            // Already subscribed, broadcast handled normally
110→            continue;
111→        }
112→
113→        // User not subscribed - emit EnsureSync
114→        // Coordinator will handle: device resolution, connection, subscription
115→        if let Some(ref sync_event_tx) = state.sync_event_tx {
116→            let event = SyncEvent::EnsureSync { user_did: user_did.clone() };
117→
118→            if let Err(e) = sync_event_tx.try_send(event) {
119→                warn!(user_did = %user_did, error = %e, "Failed to emit EnsureSync");
120→            } else {
121→                debug!(user_did = %user_did, "Emitted EnsureSync for unsubscribed target");
122→            }
123→        }
124→    }
125→}
