  1→//! Apply update handling for Scribe actor
  2→//!
  3→//! Handles incoming layer updates (local or remote), including permission checks,
  4→//! validation, and CRDT merge.
  5→//!
  6→//! Note: Derivation is now handled externally by kunki/LuaRuntime which
  7→//! subscribes to PageUpdate::LayerChanged events.
  8→//!
  9→//! ## Key Types
 10→//!
 11→//! - `UpdateContext`: Computed context for an incoming update - all decisions made upfront
 12→//! - `ApplyOutcome`: Result of applying an update (Applied or Rejected)
 13→
 14→use logging_utils::ShortLayer;
 15→use tracing::{debug, error, info, warn, instrument};
 16→
 17→use domains::Layer;
 18→
 19→use super::broadcast::{broadcast_update, notify_layer_discovered};
 20→use crate::layer_unit::LayerUnit;
 21→use crate::layer_unit::{find_matching_dynamic_schema, prepare_layer_permits};
 22→use crate::loro_observer::{set_pending_update_source, clear_pending_update_source, setup_layer_observer};
 23→use crate::permit::{Permissions, PermitContext};
 24→use crate::state::ScribeState;
 25→use crate::SyncEvent;
 26→use crate::JsonOp;
 27→use crate::state::normalize_layer_name;
 28→
 29→// Update Context - Centralized Decision Logic
 30→
 31→/// Context for an incoming update - computed once, used throughout
 32→///
 33→/// **Design**: All decisions about how to handle an update are computed upfront.
 34→/// This makes the apply flow clearer and easier to test.
 35→#[derive(Debug)]
 36→pub struct UpdateContext {
 37→    /// Layer being updated
 38→    pub layer_name: String,
 39→    /// Source of update: None = local, Some = remote peer (user_did, device_id)
 40→    pub from_peer: Option<(String, String)>,
 41→    /// Role of the peer (for validation) - "node", "owner", "viewer", etc.
 42→    pub peer_role: String,
 43→
 44→    /// Is this a remote update (from a peer)?
 45→    pub is_remote: bool,
 46→    /// Is this layer local-only (never synced)?
 47→    pub is_local_only: bool,
 48→    /// Does this update need Lua validation?
 49→    pub should_validate: bool,
 50→    /// Should we broadcast after applying?
 51→    pub should_broadcast: bool,
 52→    /// Is this a new layer (needs creation)?
 53→    pub is_new_layer: bool,
 54→}
 55→
 56→impl UpdateContext {
 57→    /// Create context for an incoming update
 58→    ///
 59→    /// **Context**: Computes all decisions based on state and update metadata
 60→    /// **Note**: Permission checks are done separately (may reject before context is useful)
 61→    pub fn new(
 62→        state: &ScribeState,
 63→        layer_name: &str,
 64→        from_peer: Option<(String, String)>,
 65→    ) -> Self {
 66→        let is_remote = from_peer.is_some();
 67→        let is_local_only = Permissions::is_local_only(layer_name);
 68→        let is_new_layer = !state.units.contains_key(layer_name);
 69→
 70→        // Determine peer role for validation
 71→        let peer_role = if let Some(ref peer) = from_peer {
 72→            get_peer_role(state, &peer.0)
 73→        } else {
 74→            "local".to_string()
 75→        };
 76→
 77→        // Should validate: remote update AND ValidationHandle exists
 78→        let should_validate = is_remote && state.validation_handle.is_some();
 79→
 80→        // Should broadcast: remote update (local updates use observer)
 81→        let should_broadcast = is_remote;
 82→
 83→        Self {
 84→            layer_name: layer_name.to_string(),
 85→            from_peer,
 86→            peer_role,
 87→            is_remote,
 88→            is_local_only,
 89→            should_validate,
 90→            should_broadcast,
 91→            is_new_layer,
 92→        }
 93→    }
 94→}
 95→
 96→// Apply Outcome - Event-Driven Pattern
 97→
 98→/// Outcome of applying an update
 99→///
100→/// **Design**: Separates the "what happened" from "what to do next"
101→/// This enables cleaner outcome handling and better error messages
102→#[derive(Debug)]
103→pub enum ApplyOutcome {
104→    /// Update was successfully applied
105→    Applied {
106→        /// Layer that was updated
107→        layer_name: String,
108→        /// Ops extracted from update (for derivation)
109→        ops: Vec<JsonOp>,
110→        /// Was a new layer created?
111→        created_layer: bool,
112→    },
113→    /// Update was rejected
114→    Rejected {
115→        /// Reason for rejection
116→        reason: String,
117→    },
118→}
119→
120→// Apply Update Handler
121→
122→/// Handle layer update (local or remote)
123→///
124→/// **Context**: Edit from UI or sync push from peer
125→/// **We do**: Permission check, validation, CRDT merge
126→/// **Broadcast**: Handled automatically by Loro observer (set up at startup)
127→/// **Returns**: Ok(()) on success, Err(message) on failure
128→#[instrument(skip(state, update, permit), fields(page_id = %state.page_id, layer = %ShortLayer(layer_name)))]
129→pub async fn handle_apply_update(
130→    state: &mut ScribeState,
131→    layer_name: &str,
132→    update: &[u8],
133→    from_peer: Option<(String, String)>,
134→    permit: Option<&str>,
135→) -> std::result::Result<(), String> {
136→    let _ = permit; // Permit is used for subscription in Courier, not here
137→
138→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
139→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
140→    let layer_name = layer_name.as_str();
141→
142→    // Build context - computes all decisions upfront
143→    let ctx = UpdateContext::new(state, layer_name, from_peer.clone());
144→
145→    // Step 1: Apply the update (with permission checks, validation, CRDT merge)
146→    let outcome = apply_update_core(state, &ctx, update).await;
147→
148→    // Step 2: Handle the outcome
149→    match outcome {
150→        ApplyOutcome::Applied { layer_name, ops: _, created_layer } => {
151→            // Mark layer as dirty for persistence
152→            if let Some(unit) = state.units.get_mut(&layer_name) {
153→                unit.mark_dirty();
154→            }
155→            debug!(layer = %layer_name, created = created_layer, "Update applied successfully");
156→
157→            // Post-apply handling for remote updates
158→            if ctx.is_remote {
159→                handle_post_apply(state, &layer_name, ctx.from_peer.clone()).await;
160→            }
161→
162→            // Node-side: detect new dynamic layers and issue permits
163→            if created_layer {
164→                if let Some(ref from_peer) = ctx.from_peer {
165→                    emit_dynamic_layer_permits(state, &layer_name, from_peer).await;
166→                }
167→            }
168→
169→            // Update sender's vector
170→            if let Some(ref peer) = ctx.from_peer {
171→                update_sender_vector(state, peer, &layer_name);
172→            }
173→
174→            // Broadcast to eligible subscribers
175→            if ctx.should_broadcast {
176→                broadcast_update(state, &layer_name, ctx.from_peer.as_ref()).await;
177→            }
178→
179→            // Note: Derivation is now handled externally by kunki/LuaRuntime
180→            // which subscribes to PageUpdate::LayerChanged events
181→
182→            Ok(())
183→        }
184→        ApplyOutcome::Rejected { reason } => {
185→            warn!(layer = %layer_name, reason = %reason, "Update rejected");
186→            Err(reason)
187→        }
188→    }
189→}
190→
191→/// Core apply logic - returns ApplyOutcome
192→///
193→/// **Context**: Separated from handle_apply_update for cleaner testing
194→/// **Returns**: ApplyOutcome::Applied or ApplyOutcome::Rejected
195→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
196→async fn apply_update_core(
197→    state: &mut ScribeState,
198→    ctx: &UpdateContext,
199→    update: &[u8],
200→) -> ApplyOutcome {
201→    // Step 1: Permission check - reject local_only layers from remote
202→    if ctx.is_remote && ctx.is_local_only {
203→        return ApplyOutcome::Rejected {
204→            reason: "local_only layer cannot be updated by remote peer".to_string(),
205→        };
206→    }
207→
208→    // Step 2: Permission check for remote updates
209→    if let Some(ref peer) = ctx.from_peer {
210→        if !Permissions::can_write(state, peer, &ctx.layer_name) {
211→            return ApplyOutcome::Rejected {
212→                reason: "Permission denied: cannot write to layer".to_string(),
213→            };
214→        }
215→    }
216→
217→    // Step 3: Extract ops for validation (using optimized pre-commit method)
218→    let extracted_ops = if ctx.should_validate {
219→        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
220→        match Layer::extract_ops_from_bytes(update) {
221→            Ok(ops) => Some(ops),
222→            Err(e) => {
223→                // Log extraction failure - validation will proceed with empty ops
224→                // This could mask invalid updates, so log at warn level
225→                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
226→                None
227→            }
228→        }
229→    } else {
230→        None
231→    };
232→
233→    // Step 4: Validate with Lua (if needed)
234→    if ctx.should_validate {
235→        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
236→            return ApplyOutcome::Rejected { reason: e };
237→        }
238→    }
239→
240→    // Step 5: Create layer if needed (remote only)
241→    let created_layer = if ctx.is_new_layer {
242→        if ctx.is_remote {
243→            create_layer_from_peer(state, &ctx.layer_name);
244→            true
245→        } else {
246→            return ApplyOutcome::Rejected {
247→                reason: "Layer not found".to_string(),
248→            };
249→        }
250→    } else {
251→        false
252→    };
253→
254→    // Step 6: Apply CRDT update
255→    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
256→        return ApplyOutcome::Rejected { reason: e };
257→    }
258→
259→    ApplyOutcome::Applied {
260→        layer_name: ctx.layer_name.clone(),
261→        ops: extracted_ops.unwrap_or_default(),
262→        created_layer,
263→    }
264→}
265→
266→// Helper Functions
267→
268→/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
269→///
270→/// **Context**: Business logic validation for remote updates
271→/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
272→/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
273→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
274→async fn validate_update_with_context(
275→    state: &ScribeState,
276→    ctx: &UpdateContext,
277→    extracted_ops: &Option<Vec<JsonOp>>,
278→) -> Result<(), String> {
279→    let Some(ref ops) = extracted_ops else {
280→        return Ok(()); // No ops to validate
281→    };
282→
283→    if ops.is_empty() {
284→        return Ok(()); // Empty ops = nothing to validate
285→    }
286→
287→    // Extract actual DID from from_peer, not the role
288→    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");
289→
290→    // Use ValidationHandle (kunki mode with presence_lib)
291→    let Some(ref validation_handle) = state.validation_handle else {
292→        // No validation available - allow update (viewer/owner mode without kunki)
293→        // This is expected in viewer/owner mode but unexpected in node mode without kunki
294→        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
295→        return Ok(());
296→    };
297→
298→    use tokio::time::{timeout, Duration};
299→
300→    let validation_future = validation_handle.validate_ops(
301→        &state.page_id,
302→        &ctx.layer_name,
303→        ops,
304→        from_did,
305→        &ctx.peer_role,
306→    );
307→
308→    match timeout(Duration::from_secs(5), validation_future).await {
309→        Ok(Ok((true, _))) => {
310→            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
311→            Ok(())
312→        }
313→        Ok(Ok((false, error_msg))) => {
314→            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
315→            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
316→            Err(format!("Validation failed: {}", msg))
317→        }
318→        Ok(Err(e)) => {
319→            warn!(layer = %ctx.layer_name, error = %e, "Validation error, rejecting update");
320→            Err(format!("Validation error: {}", e))
321→        }
322→        Err(_) => {
323→            warn!(layer = %ctx.layer_name, "Validation timeout (5s), rejecting update");
324→            Err("Validation timeout".to_string())
325→        }
326→    }
327→}
328→
329→/// Create a new layer from peer sync
330→///
331→/// **Context**: Peer sent update for a layer we don't have yet
332→/// **We do**: Create layer, set up observer, notify UI
333→#[instrument(skip(state), fields(page_id = %state.page_id))]
334→fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
335→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
336→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
337→    let layer_name = layer_name.as_str();
338→    let mut unit = LayerUnit::new_empty();
339→    unit.set_local_only(!state.should_sync_layer(layer_name));
340→    unit.mark_dirty();
341→    state.units.insert(layer_name.to_string(), unit);
342→    info!(layer = %layer_name, "Created new layer from peer sync");
343→
344→    // Set up Loro observer for new layer to enable sync broadcasts
345→    setup_layer_observer(state, layer_name);
346→
347→    // Notify UI subscribers about the new layer
348→    notify_layer_discovered(state, layer_name);
349→}
350→
351→/// Apply CRDT update to layer
352→///
353→/// **Context**: Actually merge the update into the layer
354→/// **We do**: Set pending source, apply, clear pending source
355→#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
356→fn apply_crdt_update(
357→    state: &mut ScribeState,
358→    layer_name: &str,
359→    update: &[u8],
360→    from_peer: Option<(String, String)>,
361→) -> Result<(), String> {
362→    // Set pending update source BEFORE apply() so observer knows who caused this change
363→    set_pending_update_source(state, from_peer);
364→
365→    // Get the layer and apply update
366→    let result = if let Some(unit) = state.units.get(layer_name) {
367→        unit.layer().apply(update)
368→    } else {
369→        clear_pending_update_source(state);
370→        return Err("Layer not found".to_string());
371→    };
372→
373→    if let Err(e) = result {
374→        // Clear on error too
375→        clear_pending_update_source(state);
376→        error!(error = %e, "Failed to apply update to layer");
377→        return Err(format!("Failed to apply update: {}", e));
378→    }
379→
380→    // Clear pending update source AFTER apply() (observer already captured it)
381→    clear_pending_update_source(state);
382→
383→    Ok(())
384→}
385→
386→/// Handle post-apply actions for remote updates
387→///
388→/// **Context**: Remote update was successfully applied
389→/// **We do**: Flush app layers immediately
390→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
391→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
392→async fn handle_post_apply(
393→    state: &mut ScribeState,
394→    layer_name: &str,
395→    _from_peer: Option<(String, String)>,
396→) {
397→    // For app layers, flush immediately to storage so restart loads new code
398→    if layer_name.starts_with("app:") {
399→        if let Some(unit) = state.units.get_mut(layer_name) {
400→            let snapshot = unit.layer().export_snapshot();
401→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
402→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
403→            } else {
404→                info!(layer = %layer_name, "Saved app layer immediately for restart");
405→                // Remove from dirty since we just saved it
406→                unit.clear_dirty();
407→            }
408→        }
409→    }
410→
411→    // Note: UI notification via emit_layer_changed_after_apply was removed
412→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
413→    // This prevents duplicate notifications
414→}
415→
416→/// Update sender's peer vector after receiving their update
417→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
418→fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
419→    if let Some(unit) = state.units.get(layer_name) {
420→        if let Ok(mut subs) = state.subscribers.write() {
421→            if let Some(info) = subs.get_mut(peer) {
422→                let current_vector = unit.layer().version_vector();
423→                info.vectors.insert(layer_name.to_string(), current_vector);
424→                debug!(user_did = %peer.0, "Updated sender's peer vector");
425→            }
426→        }
427→    }
428→}
429→
430→/// Detect if a newly created layer matches a dynamic schema and emit permits
431→///
432→/// **Context**: Node receives a new layer from peer. If it matches a dynamic schema,
433→/// prepare layer permits for all connected peers and emit SyncEvent::NewDynamicLayer.
434→/// **Coordinator** distributes the permits to PeerActors → peers.
435→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
436→async fn emit_dynamic_layer_permits(
437→    state: &ScribeState,
438→    layer_name: &str,
439→    from_peer: &(String, String),
440→) {
441→    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
442→    let Some(ref permit_issuer) = state.permit_issuer else { return; };
443→    let Some(ref our_permit) = state.our_permit else { return; };
444→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
445→
446→    // Check if layer matches a dynamic schema
447→    let Some((schema_key, schema, creator_did)) =
448→        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };
449→
450→    // Validate creator namespace: sender's DID must match DID in path
451→    if from_peer.0 != creator_did {
452→        warn!(
453→            layer = %layer_name,
454→            sender = %from_peer.0,
455→            creator = %creator_did,
456→            "Creator namespace mismatch — sender DID doesn't match path DID"
457→        );
458→        return;
459→    }
460→
461→    // Mark the layer as dynamic
462→    if let Some(unit) = state.units.get(layer_name) {
463→        // Note: is_dynamic is pub so we'd need get_mut, but we can't mutate here.
464→        // The flag is informational; permit issuance is the critical path.
465→        let _ = unit;
466→    }
467→
468→    // Store dynamic layer metadata (for subscription-time permit issuance)
469→    if schema.grant == gurkha::GrantType::Explicit {
470→        if let Some(ref permit_issuer) = state.permit_issuer {
471→            let initial_participants = vec![creator_did.clone()];
472→            let full_name = format!("{}/{}", state.page_id, layer_name);
473→            if let Err(e) = permit_issuer.store_layer_participants(&full_name, &initial_participants) {
474→                warn!(error = %e, "Failed to store initial participants");
475→            } else {
476→                info!(layer = %layer_name, creator = %creator_did, "Stored initial explicit layer metadata");
477→            }
478→        }
479→    }
480→
481→    // Collect connected peers with their roles
482→    let connected_peers = collect_connected_peers_with_roles(state);
483→
484→    // Prepare layer permits
485→    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
486→    match prepare_layer_permits(
487→        permit_issuer.as_ref(),
488→        &state.page_id,
489→        &full_layer_name,
490→        schema,
491→        &creator_did,
492→        &connected_peers,
493→    ) {
494→        Ok(permits) if !permits.is_empty() => {
495→            info!(
496→                layer = %layer_name,
497→                schema = %schema_key,
498→                creator = %creator_did,
499→                permit_count = permits.len(),
500→                "Prepared dynamic layer permits, emitting NewDynamicLayer"
501→            );
502→
503→            // Add layer permits to node's SubscriberInfo so can_receive_layer() works
504→            // for subsequent broadcasts. Without this, the node would prepare permits
505→            // but never actually send the layer data to subscribers.
506→            if let Ok(mut subs) = state.subscribers.write() {
507→                for ((did, _device_id), info) in subs.iter_mut() {
508→                    for (recipient_did, token) in &permits {
509→                        if did == recipient_did {
510→                            match gurkha::Permit::from_token(token) {
511→                                Ok(permit) => {
512→                                    info.add_layer_permit(permit);
513→                                    debug!(
514→                                        recipient = %did,
515→                                        layer = %layer_name,
516→                                        "Added layer permit to subscriber"
517→                                    );
518→                                }
519→                                Err(e) => {
520→                                    warn!(
521→                                        recipient = %did,
522→                                        error = %e,
523→                                        "Failed to parse layer permit for subscriber"
524→                                    );
525→                                }
526→                            }
527→                        }
528→                    }
529→                }
530→            }
531→
532→            let event = SyncEvent::NewDynamicLayer {
533→                page_id: state.page_id.clone(),
534→                layer_name: full_layer_name,
535→                permits,
536→            };
537→
538→            if let Err(e) = sync_event_tx.send(event).await {
539→                error!(error = %e, "Failed to emit NewDynamicLayer event");
540→            }
541→        }
542→        Ok(_) => {
543→            debug!(layer = %layer_name, "No permits needed for dynamic layer");
544→        }
545→        Err(e) => {
546→            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
547→        }
548→    }
549→}
550→
551→/// Collect connected peers with their roles from subscriber info
552→///
553→/// **Context**: Node needs (did, role) pairs for prepare_layer_permits
554→fn collect_connected_peers_with_roles(state: &ScribeState) -> Vec<(String, String)> {
555→    let mut peers = Vec::new();
556→
557→    if let Ok(subs) = state.subscribers.read() {
558→        for ((did, _device_id), info) in subs.iter() {
559→            let role = info.permit.relationship().unwrap_or("peer").to_string();
560→            // Avoid duplicates (same DID, different devices)
561→            if !peers.iter().any(|(d, _): &(String, String)| d == did) {
562→                peers.push((did.clone(), role));
563→            }
564→        }
565→    }
566→
567→    peers
568→}
569→
570→/// Get role for a peer from their stored permit
571→///
572→/// **Context**: Determining role for Lua validation
573→/// **Checks**:
574→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
575→/// 2. Stored permit (node mode) -> extract role from permit
576→/// 3. Default -> "peer"
577→#[instrument(skip(state), fields(page_id = %state.page_id))]
578→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
579→    // If peer is our sync target, they are the "node" from our perspective
580→    if let Some(ref config) = state.sync_config {
581→        if let Some(ref sync_target) = config.sync_target {
582→            if sync_target == peer_did {
