  1→//! Dynamic Layer Management
  2→//!
  3→//! Schema validation, path generation, and permit preparation for dynamic layers.
  4→//! Uses PermitIssuer trait — never touches signing keys directly.
  5→
  6→use tracing::{info, warn};
  7→
  8→use crate::state::ScribeState;
  9→use crate::storage::PermitIssuer;
 10→use crate::loro_observer;
 11→
 12→use super::LayerUnit;
 13→
 14→/// Handle CreateDynamicLayer message
 15→///
 16→/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
 17→/// **We do**: Validate schema exists in permit, generate full path with our DID, create layer
 18→/// **Returns**: Full layer name (bare, without page_id prefix)
 19→pub fn handle_create_dynamic_layer(
 20→    state: &mut ScribeState,
 21→    schema_key: &str,
 22→    layer_id: &str,
 23→) -> Result<String, String> {
 24→    let permit = state.our_permit.as_ref()
 25→        .ok_or_else(|| "No permit available".to_string())?;
 26→
 27→    // Validate schema exists in our permit's dynamic_layer_schemas
 28→    let schemas = permit.dynamic_layer_schemas();
 29→    let _schema = schemas.get(schema_key)
 30→        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;
 31→
 32→    // Generate full layer path with our DID
 33→    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
 34→    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
 35→    let full_name = format!("{}/{}", state.page_id, bare_path);
 36→
 37→    // Check if layer already exists
 38→    if state.units.contains_key(&bare_path) {
 39→        info!(layer = %bare_path, "Dynamic layer already exists");
 40→        return Ok(full_name);
 41→    }
 42→
 43→    // Create the layer
 44→    info!(
 45→        page_id = %state.page_id,
 46→        schema = %schema_key,
 47→        layer = %bare_path,
 48→        "Creating dynamic layer"
 49→    );
 50→    let mut unit = LayerUnit::new_empty();
 51→    unit.set_local_only(!state.should_sync_layer(&bare_path));
 52→    unit.is_dynamic = true;
 53→    state.units.insert(bare_path.clone(), unit);
 54→
 55→    // Set up observer for the new layer
 56→    loro_observer::setup_layer_observer(state, &bare_path);
 57→
 58→    Ok(full_name)
 59→}
 60→
 61→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
 62→///
 63→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
 64→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
 65→///
 66→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
 67→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
 68→    let parts: Vec<&str> = schema_key.split('/').collect();
 69→    let mut result = Vec::new();
 70→
 71→    if parts.is_empty() {
 72→        return format!("{}/{}", our_did, layer_id);
 73→    }
 74→
 75→    // First segment: literal
 76→    result.push(parts[0].to_string());
 77→
 78→    // Insert our DID as the second segment (namespace)
 79→    result.push(our_did.to_string());
 80→
 81→    // Remaining segments: replace {id} with layer_id, keep literals
 82→    for part in &parts[1..] {
 83→        if *part == "{id}" {
 84→            result.push(layer_id.to_string());
 85→        } else {
 86→            result.push(part.to_string());
 87→        }
 88→    }
 89→
 90→    result.join("/")
 91→}
 92→
 93→/// Determine recipients and create layer permits for a new dynamic layer
 94→///
 95→/// **Context**: Called by Scribe when detecting a new dynamic layer from a peer.
 96→/// **Returns**: Ready-to-send permits — courier just distributes them.
 97→/// **Uses**: PermitIssuer trait (context-aware gurkha) — never touches signing keys.
 98→pub fn prepare_layer_permits(
 99→    permit_issuer: &dyn PermitIssuer,
100→    page_id: &str,
101→    layer_name: &str,
102→    schema: &gurkha::DynamicLayerSchema,
103→    creator_did: &str,
104→    connected_peers: &[(String, String)],  // (did, role)
105→) -> Result<Vec<(String, String)>, String> {
106→    let mut permits = Vec::new();
107→
108→    match schema.grant {
109→        gurkha::GrantType::Role => {
110→            // Role-granted: all peers with matching roles get access
111→            for (did, role) in connected_peers {
112→                if let Some(perms) = schema.role_permissions.get(role) {
113→                    match permit_issuer.issue_layer_permit(did, layer_name, perms.clone()) {
114→                        Ok((token, _cid)) => {
115→                            info!(
116→                                page_id = %page_id,
117→                                layer = %layer_name,
118→                                recipient = %did,
119→                                role = %role,
120→                                "Issued role-based layer permit"
121→                            );
122→                            permits.push((did.clone(), token));
123→                        }
124→                        Err(e) => {
125→                            warn!(
126→                                page_id = %page_id,
127→                                layer = %layer_name,
128→                                recipient = %did,
129→                                error = %e,
130→                                "Failed to issue layer permit"
131→                            );
132→                        }
133→                    }
134→                }
135→            }
136→        }
137→        gurkha::GrantType::Explicit => {
138→            // Explicit-granted: creator + named participants only
139→            let default_config = schema.permissions.clone().unwrap_or(
140→                gurkha::LayerConfig { sync: true, write: true, layer_type: None }
141→            );
142→
143→            // Creator always gets access
144→            match permit_issuer.issue_layer_permit(creator_did, layer_name, default_config.clone()) {
145→                Ok((token, _cid)) => {
146→                    info!(
147→                        page_id = %page_id,
148→                        layer = %layer_name,
149→                        creator = %creator_did,
150→                        "Issued creator layer permit"
151→                    );
152→                    permits.push((creator_did.to_string(), token));
153→                }
154→                Err(e) => {
155→                    warn!(
156→                        page_id = %page_id,
157→                        layer = %layer_name,
158→                        error = %e,
159→                        "Failed to issue creator layer permit"
160→                    );
161→                }
162→            }
163→
164→            // Named participants (from layer metadata)
165→            if let Ok(participants) = permit_issuer.load_layer_participants(layer_name) {
166→                for participant_did in &participants {
167→                    // Skip creator (already issued above)
168→                    if participant_did == creator_did {
169→                        continue;
170→                    }
171→                    // Only issue to currently connected peers
172→                    if connected_peers.iter().any(|(d, _)| d == participant_did) {
173→                        match permit_issuer.issue_layer_permit(participant_did, layer_name, default_config.clone()) {
174→                            Ok((token, _cid)) => {
175→                                info!(
176→                                    page_id = %page_id,
177→                                    layer = %layer_name,
178→                                    participant = %participant_did,
179→                                    "Issued participant layer permit"
180→                                );
181→                                permits.push((participant_did.clone(), token));
182→                            }
183→                            Err(e) => {
184→                                warn!(
185→                                    page_id = %page_id,
186→                                    layer = %layer_name,
187→                                    participant = %participant_did,
188→                                    error = %e,
189→                                    "Failed to issue participant layer permit"
190→                                );
191→                            }
192→                        }
193→                    }
194→                }
195→            }
196→        }
197→    }
198→
199→    Ok(permits)
200→}
201→
202→/// Find matching dynamic schema for a layer received from a peer
203→///
204→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
205→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
206→pub fn find_matching_dynamic_schema<'a>(
207→    permit: &'a gurkha::Permit,
208→    layer_name: &str,
209→    page_id: &str,
210→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
211→    let schemas = permit.dynamic_layer_schemas();
212→    if schemas.is_empty() {
213→        return None;
214→    }
215→
216→    // Strip page_id prefix to get bare layer path
217→    let page_prefix = format!("{}/", page_id);
218→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
219→
220→    let path_parts: Vec<&str> = bare_path.split('/').collect();
221→
222→    // Path must have at least 3 segments: prefix/did/id[/suffix]
223→    if path_parts.len() < 3 {
224→        return None;
225→    }
226→
227→    // Second segment should be a DID (the creator)
228→    let potential_creator = path_parts[1];
229→    if !potential_creator.starts_with("did:") {
230→        return None;
231→    }
232→
233→    // Try each schema pattern
234→    for (schema_key, schema) in schemas {
235→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
236→
237→        // Dynamic path has one extra segment (DID) compared to pattern
238→        if path_parts.len() != pattern_parts.len() + 1 {
239→            continue;
240→        }
241→
242→        // First segment must match literally
243→        if path_parts[0] != pattern_parts[0] {
244→            continue;
245→        }
246→
247→        // path[2..] must match pattern[1..] (with {id} as wildcard)
248→        let mut matched = true;
249→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
250→            if *pat_seg != "{id}" && path_seg != pat_seg {
251→                matched = false;
252→                break;
253→            }
254→        }
255→
256→        if matched {
257→            return Some((schema_key, schema, potential_creator.to_string()));
258→        }
259→    }
260→
261→    None
262→}
263→
264→/// Validate that a layer path created by a peer matches their DID (namespace security)
265→///
266→/// **Context**: Node receives a new layer from a peer. Before accepting, verify
267→/// that the creator's DID is in the layer path (prevents namespace forgery).
268→///
269→/// **Returns**: true if the layer path contains the sender's DID
270→pub fn validate_creator_namespace(layer_name: &str, page_id: &str, sender_did: &str) -> bool {
271→    let page_prefix = format!("{}/", page_id);
272→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
273→
274→    // The creator's DID must be the second segment in the path
275→    let parts: Vec<&str> = bare_path.split('/').collect();
276→    if parts.len() < 2 {
277→        return false;
278→    }
279→
280→    parts[1] == sender_did
281→}
282→
283→/// Handle AddLayerAccess message
284→///
285→/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
286→/// **We do**: Validate capability, store participant, issue permit if peer is subscribed
287→pub async fn handle_add_layer_access(
288→    state: &ScribeState,
289→    layer_name: &str,
290→    did: &str,
291→) -> Result<(), String> {
292→    // 1. Check our permit has manage_layer_access capability
293→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
294→    if !permit.can_manage_layer_access() {
295→        return Err("No manage_layer_access capability".into());
296→    }
297→
298→    // 2. Store participant via PermitIssuer
299→    let issuer = state.permit_issuer.as_ref().ok_or("No permit issuer (not node mode)")?;
300→    let mut participants = issuer.load_layer_participants(layer_name)
301→        .map_err(|e| e.to_string())?;
302→    if !participants.contains(&did.to_string()) {
303→        participants.push(did.to_string());
304→        issuer.store_layer_participants(layer_name, &participants)
305→            .map_err(|e| e.to_string())?;
306→    }
307→
308→    // 3. If peer is currently subscribed, issue permit immediately
309→    let mut new_permits = Vec::new();
310→    if let Ok(subs) = state.subscribers.read() {
311→        for ((sub_did, _), _info) in subs.iter() {
312→            if sub_did == did {
313→                if let Some((_schema_key, schema, _creator)) =
314→                    find_matching_dynamic_schema(permit, layer_name, &state.page_id)
315→                {
316→                    let config = schema.permissions.clone().unwrap_or(
317→                        gurkha::LayerConfig { sync: true, write: true, layer_type: None }
318→                    );
319→                    match issuer.issue_layer_permit(did, layer_name, config) {
320→                        Ok((token, _cid)) => {
321→                            new_permits.push((did.to_string(), token));
322→                        }
323→                        Err(e) => {
324→                            warn!(error = %e, "Failed to issue layer permit for new participant");
325→                        }
326→                    }
327→                }
328→                break;
329→            }
330→        }
331→    }
332→
333→    // 4. Add layer permits to subscriber info (if issued)
334→    if !new_permits.is_empty() {
335→        if let Ok(mut subs) = state.subscribers.write() {
336→            for ((sub_did, _), info) in subs.iter_mut() {
337→                for (recipient, token) in &new_permits {
338→                    if sub_did == recipient {
339→                        if let Ok(p) = gurkha::Permit::from_token(token) {
340→                            info.add_layer_permit(p);
341→                        }
342→                    }
343→                }
344→            }
345→        }
346→    }
347→
348→    // 5. Emit LayerAccessChanged for Coordinator to distribute permits
349→    if !new_permits.is_empty() {
350→        if let Some(ref sync_event_tx) = state.sync_event_tx {
351→            let event = crate::SyncEvent::LayerAccessChanged {
352→                page_id: state.page_id.clone(),
353→                layer_name: layer_name.to_string(),
354→                permits: new_permits,
355→            };
356→            if let Err(e) = sync_event_tx.send(event).await {
357→                warn!(error = %e, "Failed to emit LayerAccessChanged");
358→            }
359→        }
360→    }
361→
362→    Ok(())
363→}
364→
365→/// Handle RemoveLayerAccess message
366→///
367→/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
368→/// **We do**: Validate capability, remove participant from metadata
369→pub fn handle_remove_layer_access(
370→    state: &ScribeState,
371→    layer_name: &str,
372→    did: &str,
373→) -> Result<(), String> {
374→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
375→    if !permit.can_manage_layer_access() {
376→        return Err("No manage_layer_access capability".into());
377→    }
378→
379→    let issuer = state.permit_issuer.as_ref().ok_or("No permit issuer")?;
380→    let mut participants = issuer.load_layer_participants(layer_name)
381→        .map_err(|e| e.to_string())?;
382→    participants.retain(|p| p != did);
383→    issuer.store_layer_participants(layer_name, &participants)
384→        .map_err(|e| e.to_string())?;
385→    Ok(())
386→}
