                layer.export_snapshot()
            } else {
                match layer.export_updates(their_vector) {
                    Ok(updates) if updates.is_empty() => {
                        // No new updates since their last sync
                        debug!(user_did = %user_did, layer = %layer_name, "No new updates for subscriber");
                        continue;
                    }
                    Ok(updates) => updates,
                    Err(e) => {
                        warn!(error = %e, layer = %layer_name, "Failed to export incremental, using snapshot");
                        layer.export_snapshot()
                    }
                }
            }
        } else {
            // No stored vector - send full snapshot
            layer.export_snapshot()
        };

        // Get our current state vector for 3-step sync protocol
        let state_vector = layer.version_vector();

        // Skip empty data or empty state vectors (no operations)
        // Empty LoroDoc has state_vector [0] (single byte indicating 0 entries)
        if data.is_empty() || state_vector.len() <= 1 {
            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer in initial state");
            continue;
        }

        let payload = BroadcastPayload {
            page_id: state.page_id.clone(),
            layer_name: layer_name.clone(),
            layer_type: domains::LayerType::from_layer_name(layer_name),
            update: data,
            state_vector,
        };

        if let Err(e) = broadcast_tx.try_send(payload) {
            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
        } else {
            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state to subscriber");
        }
    }
}

/// Issue pending layer permits for a newly subscribed peer (node mode only)
///
/// **Context**: Peer just subscribed. Check if they're a participant in any explicit
/// dynamic layers and issue fresh permits.
#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
async fn issue_pending_layer_permits(
    state: &ScribeState,
    user_did: &str,
    device_id: &str,
) {
    let Some(ref issuer) = state.permit_issuer else { return; };
    let Some(ref our_permit) = state.our_permit else { return; };
    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };

    // Load all explicit dynamic layers and their participants
    let explicit_layers = match issuer.list_explicit_dynamic_layers() {
        Ok(layers) => layers,
        Err(e) => { warn!(error = %e, "Failed to list explicit dynamic layers"); return; }
    };

    let mut all_permits = Vec::new();
    for (layer_name, participants) in &explicit_layers {
        if !participants.contains(&user_did.to_string()) { continue; }

        // Find schema for permissions
        if let Some((_key, schema, _creator)) =
            find_matching_dynamic_schema(our_permit, layer_name, &state.page_id)
        {
            let config = schema.permissions.clone().unwrap_or(
                gurkha::LayerConfig { sync: true, write: true, layer_type: None }
            );
            match issuer.issue_layer_permit(user_did, layer_name, config) {
                Ok((token, _cid)) => {
                    // Add to subscriber's layer_permits
                    if let Ok(mut subs) = state.subscribers.write() {
                        if let Some(info) = subs.get_mut(&(user_did.to_string(), device_id.to_string())) {
                            if let Ok(p) = gurkha::Permit::from_token(&token) {
                                info.add_layer_permit(p);
                            }
                        }
                    }
                    all_permits.push((user_did.to_string(), token));
                }
                Err(e) => warn!(error = %e, layer = %layer_name, "Failed to issue pending layer permit"),
            }
        }
    }

    // Emit permits for distribution via Coordinator
    if !all_permits.is_empty() {
        let event = SyncEvent::NewDynamicLayer {
            page_id: state.page_id.clone(),
            layer_name: "pending-layer-permits".to_string(),
            permits: all_permits,
        };
        if let Err(e) = sync_event_tx.send(event).await {
            warn!(error = %e, "Failed to emit pending layer permits");
        }
    }
}

