824→
825→            ScribeMessage::GetSubscriberCount { reply } => {
826→                let count = state.subscribers.read()
827→                    .map(|s| s.len())
828→                    .unwrap_or(0);
829→                let _ = reply.send(count);
830→            }
831→
832→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
833→                // RefreshApp requires filesystem access which is handled by butler's refresh service
834→                // This stub returns an error - callers should use butler's refresh functionality instead
835→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
836→            }
837→        }
838→
839→        Ok(())
840→    }
841→
842→    #[instrument(skip_all, fields(page_id = %state.page_id))]
843→    async fn post_stop(
844→        &self,
845→        _myself: ActorRef<Self::Msg>,
846→        state: &mut Self::State,
847→    ) -> std::result::Result<(), ActorProcessingErr> {
848→        // Flush any dirty layers before stopping
849→        let has_dirty = state.units.values().any(|u| u.is_dirty());
850→        if has_dirty {
851→            let dirty_count = state.units.values().filter(|u| u.is_dirty()).count();
852→            info!(page_id = %state.page_id, dirty_count = dirty_count, "Flushing dirty layers on shutdown");
853→            sync::handle_flush(state).await;
854→        }
855→
856→        // Stop node script if running
857→        if let Some(tx) = state.node_script_shutdown.take() {
858→            info!(page_id = %state.page_id, "Stopping node script tick loop");
859→            let _ = tx.send(()).await;
860→        }
861→
862→        info!(page_id = %state.page_id, "Scribe stopped");
863→        Ok(())
864→    }
865→}
866→
867→// Helper Methods
868→
869→impl Scribe {
870→    /// Handle JSON update from UI (CEL commit())
871→    ///
872→    /// **Broadcast**: Handled automatically by Loro observer after commit()
873→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
874→    async fn handle_update_from_json(
875→        &self,
876→        state: &mut ScribeState,
877→        layer_name: &str,
878→        path: &str,
879→        value: serde_json::Value,
880→    ) -> Result<()> {
881→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
882→
883→        // Get or create the layer unit
884→        let unit = state
885→            .units
886→            .entry(layer_name.to_string())
887→            .or_insert_with(LayerUnit::new_empty);
888→
889→        // Convert JSON to Loro and update
890→        unit.layer()
891→            .set_from_json(path, &value)
892→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
893→
894→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
895→        unit.layer().commit();
896→
897→        // Mark as dirty for persistence
898→        unit.mark_dirty();
899→
900→        debug!("Layer update from JSON complete, observer will broadcast");
901→        Ok(())
902→    }
903→}
904→
905→// Tests
906→
907→#[cfg(test)]
908→mod tests {
909→    use super::*;
910→    use crate::test_fixtures::node_scribe_args;
911→    use std::time::Duration;
912→
913→    /// Test that Scribe with no subscribers doesn't crash on ephemeral send
914→    #[tokio::test]
915→    async fn test_ephemeral_with_no_subscribers() {
916→        let args = node_scribe_args("test-page-456");
917→        let (scribe_ref, _handle) = ractor::Actor::spawn(
918→            Some("test-scribe-no-subs".to_string()),
919→            Scribe,
920→            args,
921→        ).await.expect("Failed to spawn Scribe");
922→
923→        // Send ephemeral with no subscribers - should not crash
924→        scribe_ref.cast(ScribeMessage::SendStructuredEphemeral {
925→            func: "typing".to_string(),
926→            args: serde_json::json!({"user": "TestUser"}),
927→        }).expect("Failed to send ephemeral");
928→
929→        // Small delay to ensure message is processed
930→        tokio::time::sleep(Duration::from_millis(50)).await;
931→
932→        println!("✓ Ephemeral with no subscribers handled gracefully");
933→        scribe_ref.stop(Some("test complete".to_string()));
934→    }
935→}
