  1→//! Apply update handling for Scribe actor
  2→//!
  3→//! Handles incoming layer updates (local or remote), including permission checks,
  4→//! validation, and CRDT merge.
  5→//!
  6→//! Note: Derivation is now handled externally by kunki/LuaRuntime which
  7→//! subscribes to PageUpdate::LayerChanged events.
  8→//!
  9→//! ## Key Types
 10→//!
 11→//! - `UpdateContext`: Computed context for an incoming update - all decisions made upfront
 12→//! - `ApplyOutcome`: Result of applying an update (Applied or Rejected)
 13→
 14→use logging_utils::ShortLayer;
 15→use tracing::{debug, error, info, warn, instrument};
 16→
 17→use domains::Layer;
 18→
 19→use super::broadcast::{broadcast_update, notify_layer_discovered};
 20→use crate::layer_unit::LayerUnit;
 21→use crate::layer_unit::{find_matching_dynamic_schema, prepare_layer_permits};
 22→use crate::loro_observer::{set_pending_update_source, clear_pending_update_source, setup_layer_observer};
 23→use crate::permit::{Permissions, PermitContext};
 24→use crate::state::ScribeState;
 25→use crate::SyncEvent;
 26→use crate::JsonOp;
 27→use crate::state::normalize_layer_name;
 28→
 29→// Update Context - Centralized Decision Logic
 30→
 31→/// Context for an incoming update - computed once, used throughout
 32→///
 33→/// **Design**: All decisions about how to handle an update are computed upfront.
 34→/// This makes the apply flow clearer and easier to test.
 35→#[derive(Debug)]
 36→pub struct UpdateContext {
 37→    /// Layer being updated
 38→    pub layer_name: String,
 39→    /// Source of update: None = local, Some = remote peer (user_did, device_id)
 40→    pub from_peer: Option<(String, String)>,
 41→    /// Role of the peer (for validation) - "node", "owner", "viewer", etc.
 42→    pub peer_role: String,
 43→
 44→    /// Is this a remote update (from a peer)?
 45→    pub is_remote: bool,
 46→    /// Is this layer local-only (never synced)?
 47→    pub is_local_only: bool,
 48→    /// Does this update need Lua validation?
 49→    pub should_validate: bool,
 50→    /// Should we broadcast after applying?
 51→    pub should_broadcast: bool,
 52→    /// Is this a new layer (needs creation)?
 53→    pub is_new_layer: bool,
 54→}
 55→
 56→impl UpdateContext {
 57→    /// Create context for an incoming update
 58→    ///
 59→    /// **Context**: Computes all decisions based on state and update metadata
 60→    /// **Note**: Permission checks are done separately (may reject before context is useful)
 61→    pub fn new(
 62→        state: &ScribeState,
 63→        layer_name: &str,
 64→        from_peer: Option<(String, String)>,
 65→    ) -> Self {
 66→        let is_remote = from_peer.is_some();
 67→        let is_local_only = Permissions::is_local_only(layer_name);
 68→        let is_new_layer = !state.units.contains_key(layer_name);
 69→
 70→        // Determine peer role for validation
 71→        let peer_role = if let Some(ref peer) = from_peer {
 72→            get_peer_role(state, &peer.0)
 73→        } else {
 74→            "local".to_string()
 75→        };
 76→
 77→        // Should validate: remote update AND ValidationHandle exists
 78→        let should_validate = is_remote && state.validation_handle.is_some();
 79→
 80→        // Should broadcast: remote update (local updates use observer)
 81→        let should_broadcast = is_remote;
 82→
 83→        Self {
 84→            layer_name: layer_name.to_string(),
 85→            from_peer,
 86→            peer_role,
 87→            is_remote,
 88→            is_local_only,
 89→            should_validate,
 90→            should_broadcast,
 91→            is_new_layer,
 92→        }
 93→    }
 94→}
 95→
 96→// Apply Outcome - Event-Driven Pattern
 97→
 98→/// Outcome of applying an update
 99→///
100→/// **Design**: Separates the "what happened" from "what to do next"
101→/// This enables cleaner outcome handling and better error messages
102→#[derive(Debug)]
103→pub enum ApplyOutcome {
104→    /// Update was successfully applied
105→    Applied {
106→        /// Layer that was updated
107→        layer_name: String,
108→        /// Ops extracted from update (for derivation)
109→        ops: Vec<JsonOp>,
110→        /// Was a new layer created?
111→        created_layer: bool,
112→    },
113→    /// Update was rejected
114→    Rejected {
115→        /// Reason for rejection
116→        reason: String,
117→    },
118→}
119→
120→// Apply Update Handler
121→
122→/// Handle layer update (local or remote)
123→///
124→/// **Context**: Edit from UI or sync push from peer
125→/// **We do**: Permission check, validation, CRDT merge
126→/// **Broadcast**: Handled automatically by Loro observer (set up at startup)
127→/// **Returns**: Ok(()) on success, Err(message) on failure
128→#[instrument(skip(state, update, permit), fields(page_id = %state.page_id, layer = %ShortLayer(layer_name)))]
129→pub async fn handle_apply_update(
130→    state: &mut ScribeState,
131→    layer_name: &str,
132→    update: &[u8],
133→    from_peer: Option<(String, String)>,
134→    permit: Option<&str>,
135→) -> std::result::Result<(), String> {
136→    let _ = permit; // Permit is used for subscription in Courier, not here
137→
138→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
139→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
140→    let layer_name = layer_name.as_str();
141→
142→    // Build context - computes all decisions upfront
143→    let ctx = UpdateContext::new(state, layer_name, from_peer.clone());
144→
145→    // Step 1: Apply the update (with permission checks, validation, CRDT merge)
146→    let outcome = apply_update_core(state, &ctx, update).await;
147→
148→    // Step 2: Handle the outcome
149→    match outcome {
150→        ApplyOutcome::Applied { layer_name, ops: _, created_layer } => {
151→            // Mark layer as dirty for persistence
152→            if let Some(unit) = state.units.get_mut(&layer_name) {
153→                unit.mark_dirty();
154→            }
155→            debug!(layer = %layer_name, created = created_layer, "Update applied successfully");
156→
157→            // Post-apply handling for remote updates
158→            if ctx.is_remote {
159→                handle_post_apply(state, &layer_name, ctx.from_peer.clone()).await;
160→            }
161→
162→            // Node-side: detect new dynamic layers and issue permits
163→            if created_layer {
164→                if let Some(ref from_peer) = ctx.from_peer {
165→                    emit_dynamic_layer_permits(state, &layer_name, from_peer).await;
166→                }
167→            }
168→
169→            // Update sender's vector
170→            if let Some(ref peer) = ctx.from_peer {
171→                update_sender_vector(state, peer, &layer_name);
172→            }
173→
174→            // Broadcast to eligible subscribers
175→            if ctx.should_broadcast {
176→                broadcast_update(state, &layer_name, ctx.from_peer.as_ref()).await;
177→            }
178→
179→            // Note: Derivation is now handled externally by kunki/LuaRuntime
180→            // which subscribes to PageUpdate::LayerChanged events
181→
182→            Ok(())
183→        }
184→        ApplyOutcome::Rejected { reason } => {
185→            warn!(layer = %layer_name, reason = %reason, "Update rejected");
186→            Err(reason)
187→        }
188→    }
189→}
190→
191→/// Core apply logic - returns ApplyOutcome
192→///
193→/// **Context**: Separated from handle_apply_update for cleaner testing
194→/// **Returns**: ApplyOutcome::Applied or ApplyOutcome::Rejected
195→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
196→async fn apply_update_core(
197→    state: &mut ScribeState,
198→    ctx: &UpdateContext,
199→    update: &[u8],
200→) -> ApplyOutcome {
201→    // Step 1: Permission check - reject local_only layers from remote
202→    if ctx.is_remote && ctx.is_local_only {
203→        return ApplyOutcome::Rejected {
204→            reason: "local_only layer cannot be updated by remote peer".to_string(),
205→        };
206→    }
207→
208→    // Step 2: Permission check for remote updates
209→    if let Some(ref peer) = ctx.from_peer {
210→        if !Permissions::can_write(state, peer, &ctx.layer_name) {
211→            return ApplyOutcome::Rejected {
212→                reason: "Permission denied: cannot write to layer".to_string(),
213→            };
214→        }
215→    }
216→
217→    // Step 3: Extract ops for validation (using optimized pre-commit method)
218→    let extracted_ops = if ctx.should_validate {
219→        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
220→        match Layer::extract_ops_from_bytes(update) {
221→            Ok(ops) => Some(ops),
222→            Err(e) => {
223→                // Log extraction failure - validation will proceed with empty ops
224→                // This could mask invalid updates, so log at warn level
225→                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
226→                None
227→            }
228→        }
229→    } else {
230→        None
231→    };
232→
233→    // Step 4: Validate with Lua (if needed)
234→    if ctx.should_validate {
235→        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
236→            return ApplyOutcome::Rejected { reason: e };
237→        }
238→    }
239→
240→    // Step 5: Create layer if needed (remote only)
241→    let created_layer = if ctx.is_new_layer {
242→        if ctx.is_remote {
243→            create_layer_from_peer(state, &ctx.layer_name);
244→            true
245→        } else {
246→            return ApplyOutcome::Rejected {
247→                reason: "Layer not found".to_string(),
248→            };
249→        }
250→    } else {
251→        false
252→    };
253→
254→    // Step 6: Apply CRDT update
255→    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
256→        return ApplyOutcome::Rejected { reason: e };
257→    }
258→
259→    ApplyOutcome::Applied {
260→        layer_name: ctx.layer_name.clone(),
261→        ops: extracted_ops.unwrap_or_default(),
262→        created_layer,
263→    }
264→}
265→
266→// Helper Functions
267→
268→/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
269→///
270→/// **Context**: Business logic validation for remote updates
271→/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
272→/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
273→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
274→async fn validate_update_with_context(
275→    state: &ScribeState,
276→    ctx: &UpdateContext,
277→    extracted_ops: &Option<Vec<JsonOp>>,
278→) -> Result<(), String> {
279→    let Some(ref ops) = extracted_ops else {
280→        return Ok(()); // No ops to validate
281→    };
282→
283→    if ops.is_empty() {
284→        return Ok(()); // Empty ops = nothing to validate
285→    }
286→
287→    // Extract actual DID from from_peer, not the role
288→    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");
289→
290→    // Use ValidationHandle (kunki mode with presence_lib)
291→    let Some(ref validation_handle) = state.validation_handle else {
292→        // No validation available - allow update (viewer/owner mode without kunki)
293→        // This is expected in viewer/owner mode but unexpected in node mode without kunki
294→        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
295→        return Ok(());
296→    };
297→
298→    use tokio::time::{timeout, Duration};
299→
300→    let validation_future = validation_handle.validate_ops(
301→        &state.page_id,
302→        &ctx.layer_name,
303→        ops,
304→        from_did,
305→        &ctx.peer_role,
306→    );
307→
308→    match timeout(Duration::from_secs(5), validation_future).await {
309→        Ok(Ok((true, _))) => {
310→            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
311→            Ok(())
312→        }
313→        Ok(Ok((false, error_msg))) => {
314→            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
315→            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
316→            Err(format!("Validation failed: {}", msg))
317→        }
318→        Ok(Err(e)) => {
319→            warn!(layer = %ctx.layer_name, error = %e, "Validation error, rejecting update");
320→            Err(format!("Validation error: {}", e))
321→        }
322→        Err(_) => {
323→            warn!(layer = %ctx.layer_name, "Validation timeout (5s), rejecting update");
324→            Err("Validation timeout".to_string())
325→        }
326→    }
327→}
328→
329→/// Create a new layer from peer sync
330→///
331→/// **Context**: Peer sent update for a layer we don't have yet
332→/// **We do**: Create layer, set up observer, notify UI
333→#[instrument(skip(state), fields(page_id = %state.page_id))]
334→fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
335→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
336→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
337→    let layer_name = layer_name.as_str();
338→    let mut unit = LayerUnit::new_empty();
339→    unit.set_local_only(!state.should_sync_layer(layer_name));
340→    unit.mark_dirty();
341→    state.units.insert(layer_name.to_string(), unit);
342→    info!(layer = %layer_name, "Created new layer from peer sync");
343→
344→    // Authorize existing subscribers for this new layer
345→    if let Ok(subs) = state.subscribers.read() {
346→        for ((did, _), info) in subs.iter() {
347→            if info.can_receive_layer(layer_name, &state.page_id) {
348→                if let Some(unit) = state.units.get(layer_name) {
349→                    unit.authorize_did(did);
350→                    state.emit_layer_auth_capture(layer_name, did, "authorized_subscriber");
351→                }
352→            }
353→        }
354→    }
355→
356→    // Apply any pending authorizations (from AuthorizeLayerSubscriber before layer creation)
357→    if let Some(pending_dids) = state.pending_layer_authorizations.remove(layer_name) {
358→        if let Some(unit) = state.units.get(layer_name) {
359→            for did in &pending_dids {
360→                unit.authorize_did(did);
361→                state.emit_layer_auth_capture(layer_name, did, "applied_pending");
362→                info!(layer = %layer_name, did = %did, "Applied pending layer authorization");
363→            }
364→        }
365→    }
366→
367→    // Set up Loro observer for new layer to enable sync broadcasts
368→    setup_layer_observer(state, layer_name);
369→
370→    // Notify UI subscribers about the new layer
371→    notify_layer_discovered(state, layer_name);
372→}
373→
374→/// Apply CRDT update to layer
375→///
376→/// **Context**: Actually merge the update into the layer
377→/// **We do**: Set pending source, apply, clear pending source
378→#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
379→fn apply_crdt_update(
380→    state: &mut ScribeState,
381→    layer_name: &str,
382→    update: &[u8],
383→    from_peer: Option<(String, String)>,
384→) -> Result<(), String> {
385→    // Set pending update source BEFORE apply() so observer knows who caused this change
386→    set_pending_update_source(state, from_peer);
387→
388→    // Get the layer and apply update
389→    let result = if let Some(unit) = state.units.get(layer_name) {
390→        unit.layer().apply(update)
391→    } else {
392→        clear_pending_update_source(state);
393→        return Err("Layer not found".to_string());
394→    };
395→
396→    if let Err(e) = result {
397→        // Clear on error too
398→        clear_pending_update_source(state);
399→        error!(error = %e, "Failed to apply update to layer");
400→        return Err(format!("Failed to apply update: {}", e));
401→    }
402→
403→    // Clear pending update source AFTER apply() (observer already captured it)
404→    clear_pending_update_source(state);
405→
406→    Ok(())
407→}
408→
409→/// Handle post-apply actions for remote updates
410→///
411→/// **Context**: Remote update was successfully applied
412→/// **We do**: Flush app layers immediately
413→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
414→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
415→async fn handle_post_apply(
416→    state: &mut ScribeState,
417→    layer_name: &str,
418→    _from_peer: Option<(String, String)>,
419→) {
420→    // For app layers, flush immediately to storage so restart loads new code
421→    if layer_name.starts_with("app:") {
422→        if let Some(unit) = state.units.get_mut(layer_name) {
423→            let snapshot = unit.layer().export_snapshot();
424→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
425→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
426→            } else {
427→                info!(layer = %layer_name, "Saved app layer immediately for restart");
428→                // Remove from dirty since we just saved it
429→                unit.clear_dirty();
430→            }
431→        }
432→    }
433→
434→    // Note: UI notification via emit_layer_changed_after_apply was removed
435→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
436→    // This prevents duplicate notifications
437→}
438→
439→/// Update sender's peer vector after receiving their update
440→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
441→fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
442→    if let Some(unit) = state.units.get(layer_name) {
443→        if let Ok(mut subs) = state.subscribers.write() {
444→            if let Some(info) = subs.get_mut(peer) {
445→                let current_vector = unit.layer().version_vector();
446→                info.vectors.insert(layer_name.to_string(), current_vector);
447→                debug!(user_did = %peer.0, "Updated sender's peer vector");
448→            }
449→        }
450→    }
451→}
452→
453→/// Detect if a newly created layer matches a dynamic schema and emit permits
454→///
455→/// **Context**: Node receives a new layer from peer. If it matches a dynamic schema,
456→/// prepare layer permits for all connected peers and emit SyncEvent::NewDynamicLayer.
457→/// **Coordinator** distributes the permits to PeerActors → peers.
458→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
459→async fn emit_dynamic_layer_permits(
460→    state: &ScribeState,
461→    layer_name: &str,
462→    from_peer: &(String, String),
463→) {
464→    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
465→    let Some(ref permit_issuer) = state.permit_issuer else { return; };
466→    let Some(ref our_permit) = state.our_permit else { return; };
467→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
468→
469→    // Check if layer matches a dynamic schema
470→    let Some((schema_key, schema, creator_did)) =
471→        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };
472→
473→    // Validate creator namespace: sender's DID must match DID in path
474→    if from_peer.0 != creator_did {
475→        warn!(
476→            layer = %layer_name,
477→            sender = %from_peer.0,
478→            creator = %creator_did,
479→            "Creator namespace mismatch — sender DID doesn't match path DID"
480→        );
481→        return;
482→    }
483→
484→    // Mark the layer as dynamic
485→    if let Some(unit) = state.units.get(layer_name) {
486→        // Note: is_dynamic is pub so we'd need get_mut, but we can't mutate here.
487→        // The flag is informational; permit issuance is the critical path.
488→        let _ = unit;
489→    }
490→
491→    // Store dynamic layer metadata (for subscription-time permit issuance)
492→    if schema.grant == gurkha::GrantType::Explicit {
493→        if let Some(ref permit_issuer) = state.permit_issuer {
494→            let initial_participants = vec![creator_did.clone()];
495→            let full_name = format!("{}/{}", state.page_id, layer_name);
496→            if let Err(e) = permit_issuer.store_layer_participants(&full_name, &initial_participants) {
497→                warn!(error = %e, "Failed to store initial participants");
498→            } else {
499→                info!(layer = %layer_name, creator = %creator_did, "Stored initial explicit layer metadata");
500→            }
501→        }
502→    }
503→
504→    // Collect connected peers with their roles
505→    let connected_peers = collect_connected_peers_with_roles(state);
506→
507→    // Prepare layer permits
508→    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
509→    match prepare_layer_permits(
510→        permit_issuer.as_ref(),
511→        &state.page_id,
512→        &full_layer_name,
513→        schema,
514→        &creator_did,
515→        &connected_peers,
516→    ) {
517→        Ok(permits) if !permits.is_empty() => {
518→            info!(
519→                layer = %layer_name,
520→                schema = %schema_key,
521→                creator = %creator_did,
522→                permit_count = permits.len(),
523→                "Prepared dynamic layer permits, emitting NewDynamicLayer"
524→            );
525→
526→            // Authorize recipient DIDs on the LayerUnit for broadcast
527→            if let Some(unit) = state.units.get(layer_name) {
528→                for (recipient_did, _token) in &permits {
529→                    unit.authorize_did(recipient_did);
530→                    state.emit_layer_auth_capture(layer_name, recipient_did, "authorized_dynamic_permit");
531→                    debug!(
532→                        recipient = %recipient_did,
533→                        layer = %layer_name,
534→                        "Authorized subscriber for dynamic layer"
535→                    );
536→                }
537→            }
538→
539→            let event = SyncEvent::NewDynamicLayer {
540→                page_id: state.page_id.clone(),
541→                layer_name: full_layer_name,
542→                permits,
543→            };
544→
545→            state.emit_sync_event_capture(&event);
546→            if let Err(e) = sync_event_tx.send(event).await {
547→                error!(error = %e, "Failed to emit NewDynamicLayer event");
548→            }
549→        }
550→        Ok(_) => {
551→            debug!(layer = %layer_name, "No permits needed for dynamic layer");
552→        }
553→        Err(e) => {
554→            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
555→        }
556→    }
557→}
558→
559→/// Collect connected peers with their roles from subscriber info
560→///
561→/// **Context**: Node needs (did, role) pairs for prepare_layer_permits
562→fn collect_connected_peers_with_roles(state: &ScribeState) -> Vec<(String, String)> {
563→    let mut peers = Vec::new();
564→
565→    if let Ok(subs) = state.subscribers.read() {
566→        for ((did, _device_id), info) in subs.iter() {
567→            let role = info.permit.relationship().unwrap_or("peer").to_string();
568→            // Avoid duplicates (same DID, different devices)
569→            if !peers.iter().any(|(d, _): &(String, String)| d == did) {
570→                peers.push((did.clone(), role));
571→            }
572→        }
573→    }
574→
575→    peers
576→}
577→
578→/// Get role for a peer from their stored permit
579→///
580→/// **Context**: Determining role for Lua validation
581→/// **Checks**:
582→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
583→/// 2. Stored permit (node mode) -> extract role from permit
584→/// 3. Default -> "peer"
585→#[instrument(skip(state), fields(page_id = %state.page_id))]
586→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
587→    // If peer is our sync target, they are the "node" from our perspective
588→    if let Some(ref config) = state.sync_config {
589→        if let Some(ref sync_target) = config.sync_target {
590→            if sync_target == peer_did {
591→                return "node".to_string();
592→            }
593→        }
594→    }
595→
596→    // Node mode: look up peer's stored permit and extract role via PermitContext
597→    if let Some(ref resolver) = state.peer_resolver {
598→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
599→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
600→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
601→                .unwrap_or_else(|_| "peer".to_string());
602→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
603→            return role;
604→        }
605→    }
606→
607→    // Default role
608→    "peer".to_string()
609→}
610→

