    decide_delegation,
    extract_issue_template,
    extract_facts_from_token,
};

// Re-export resource token decisions
pub use resource::{
    decide_space_owner_token,
    decide_space_node_to_owner_token,
    decide_page_owner_token,
};

// Re-export sync decisions
pub use sync::{
    SyncContext,
    should_send_updates,
    can_receive_updates,
    should_request_updates,
};

// Re-export consent decisions
pub use consent::{
    decide_sync_space_consent,
    decide_sync_page_consent,
    decide_sync_layer_consent,
};

// Re-export layer authorization
pub use layer::{can_access_layer, can_access_with_layer_permits, matches_creator_schema};

/// Schema for dynamically-created layers (channels, DMs, orders)
///
/// Dynamic layers are created at runtime and granted via permit re-issuance.
/// The schema defines what types of dynamic layers an app supports.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DynamicLayerSchema {
    /// Layer type: "map", "list", "text"
    #[serde(rename = "type", default)]
    pub layer_type: String,
    /// Grant type: "role" (all peers) or "explicit" (named participants)
    #[serde(default)]
    pub grant: GrantType,
    /// Permissions per role (for role-granted schemas)
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub role_permissions: HashMap<String, LayerConfig>,
    /// Permissions for explicit grants
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub permissions: Option<LayerConfig>,
}

/// How a dynamic layer is granted to peers
#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum GrantType {
    /// Granted to all peers of matching roles
    #[default]
    Role,
    /// Granted only to explicitly named participants
    Explicit,

